quests[54042] = { id = 54042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger an der Dunkelküste", description = "Ich habe verstörende Berichte von der Dunkelküste erhalten.\n\nWas einst eine sichere Hochburg der Horde war, ist jetzt von einer unnatürlichen Dunkelheit befallen. Der Mond ist vollkommen schwarz geworden.\n\nDie Außenposten dort benötigen noch immer Verstärkung durch die Hauptmacht unserer Truppen. Wir sind dem Feind zahlenmäßig unterlegen. Trefft Euch mit Nathanos an der Dunkelküste, um herauszufinden, was passiert ist.", sourceObjective = "Sprecht mit Schreckensadmiralin Segelriss, um zur Dunkelküste zu reisen und Euch bei Nathanos zu melden.", completion = "Ihr kommt gerade rechtzeitig. Wir haben ein Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[54043] = { id = 54043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Waldläufer dunkle Wiederkehr", description = "Durch diese Hinterhalte der Nachtelfen sind wir nun unterbesetzt. Wir brauchen Verstärkung, wenn wir die Dunkelküste halten wollen.\n\nBrynja, eine Val'kyr der Dunklen Fürstin, kann uns Verstärkung zur Verfügung stellen. Tötet die Nachtelfen und befehlt ihr, sie in unsere Dienste zu stellen. Sollten sich welche von ihnen weigern... kümmert Euch um sie.\n\nHabe ich mich nicht klar genug ausgedrückt? Geht. Die Dunkle Fürstin hat Pläne für diese Dunklen Waldläufer.", sourceObjective = "Tötet rachsüchtige Schildwachen und Bogenschützen und befehlt Brynja, sie als Dunkle Waldläufer wiederauferstehen zu lassen.", completion = "Wie schnell sie sich doch gegen ihre eigene Göttin gewandt haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54044] = { id = 54044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwarzer Mond am Himmel", description = "Die Dunkelküste war noch nie dafür bekannt, besonders hell und sonnig zu sein, aber etwas Merkwürdiges ist geschehen. Ein schwarzer Mond hängt über allem.\n\nKeiner der Späher, die ich in den Wald geschickt habe, ist zurückgekehrt. Die Nachtelfen führen irgendwas im Schilde. Und ich muss wissen, was.\n\nIhr Fußvolk wird die Informationen, nach denen wir suchen, nicht haben. Jagt ihre Leutnants und bringt sie mit allen Mitteln zum Reden.", sourceObjective = "Verhört die Leutnants Golras, Ivyth und Maliyra.", progress = "<Der Irrwisch wirkt verloren und desorientiert. Er folgt Euch.>", completion = "<Der Irrwisch schwebt auf und ab, als ob er benommen wäre.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54045] = { id = 54045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgerankt", description = "Es ist furchtbar, {name}! Wir haben Ernter, die nicht ernten!\n\nWir haben uns krumm und bucklig gearbeitet, um all diese Bäume zu fällen, aber jemand sorgt immer wieder dafür, dass unsere Maschinen sich in den Ranken verfangen! Ich geh nicht da raus, solange diese Nachtelfen hier herumlungern.\n\nSeht, ob es Euch gelingt, meine Produktionsmittel zu befreien!", sourceObjective = "Befreit Goblinernter aus den Ranken.", completion = "Schon besser! Sobald der Boss diese Nachtelfen losgeworden ist, haben wir auch kein Holzproblem mehr!", sourceObjectiveStatus = "unverified-source-field" }
quests[54046] = { id = 54046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verirrwischt", description = "<Der Irrwisch flackert verwirrt zu Euch herüber. Er will Euch anscheinend folgen.\n\nVielleicht hat er die Informationen, nach denen Nathanos sucht.>", sourceObjective = "Bringt den verlorenen Irrwisch zu Nathanos Pestrufer an der Lor'danellandung.", completion = "Das habe ich eigentlich nicht gemeint, als ich sagte, dass Ihr etwas Nützliches mit zurückbringen sollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54047] = { id = 54047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Hoffnung stirbt", description = "Wir müssen die Befehle der Dunklen Fürstin umsetzen, bevor wir von diesen wiedererstarkten Elfen überrannt werden.\n\nWir müssen eine ganz bestimmte Nachtelfe finden. Vielleicht erinnert Ihr Euch an sie von unserem letzten Vorstoß an die Dunkelküste. Zum Glück für Euch ist sie bereits tot. Sie sollte also weniger Probleme bereiten als die lebenden, denen Ihr bereits begegnet seid.\n\nGebt mir ein Zeichen, wenn Ihr ihren Leichnam gefunden habt.", sourceObjective = "Findet den Leichnam von Delaryn Sommermond.", completion = "Ich habe Euch losgeschickt, um eine tote Nachtelfe zu finden. Allem Anschein nach habt Ihr Euch selbst übertroffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54048] = { id = 54048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer die Wächterin stört", description = "<Das bedrückende Gefühl, dass Ihr verfolgt werdet, ist unerträglich geworden.\n\nIhr wisst, dass jemand hinter Euch ist.>", sourceObjective = "Besiegt Sira Mondhüter.", sourceObjectiveStatus = "unverified-source-field" }
quests[54049] = { id = 54049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Nacht", description = "Dies ist der Kernpunkt des Plans der Dunklen Fürstin für die Dunkelküste. Wir werden genau hier neue Champions für die Verlassenen und die Horde auferstehen lassen.\n\nBewacht die Val'kyr. Wir dürfen nicht zulassen, dass jemand oder etwas sie unterbricht.", sourceObjective = "Schützt die Val'kyr, während Delaryn und Sira wiederbelebt werden.", completion = "Ihr habt es herausgeschafft! Gut!\n\nIch auch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54050] = { id = 54050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachspiel", description = "Wir haben alle unsere Gründe, das Geschenk der Val'kyr anzunehmen. Doch jetzt ist nicht der Zeitpunkt für derartige Diskussionen.\n\nSylvanas musste heute mit dem Verlust von Brynja einen schweren Rückschlag hinnehmen. Wir werden keine Zeit zum Ausruhen haben, bevor die Allianz über diesen Ort herfällt.\n\nNathanos hat Euch zu sich gerufen. Er will Euch etwas zeigen.", sourceObjective = "Sprecht mit Nathanos Pestrufer.", completion = "Was wir jetzt machen? Uns auf die Schlacht vorbereiten.\n\nSie werden alle bezahlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54051] = { id = 54051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[54052] = { id = 54052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Questfall", description = "Ich entschuldige mich, Kumpel! Neu am Bogen! Hab eher einen Schwertarm, was?!\n\nWollte Euch nicht so erschrecken! Es ist nur, dass wir hier etwas in der Klemme stecken, meine Wenigkeit und die Besatzung hier!\n\nKönnt Ihr uns etwas helfen?! Ein paar aufrecht laufende Hunde haben uns mitten in der Nacht angegriffen! Haben uns in Unterwäsche aus dem Lager gejagt!\n\nVielleicht könnt Ihr helfen? Der Boss war etwas größer als die anderen! Wir haben ihn Bellpranke genannt, weil er uns angebellt hat und Riesenpranken hatte!", sourceObjective = "Tötet 8 Gnolle der Flusspfoten und besiegt Bellpranke.", sourceObjectiveStatus = "unverified-source-field" }
quests[54058] = { id = 54058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbeabsichtigte Konsequenzen", description = "<Xal'atath spricht erneut.>\n\nDie Diener von N'Zoth bereiten sich auf die Rückkehr des Meisters vor. Sie beabsichtigen, einen verheerenden Sturm heraufzubeschwören, um alle Ungläubigen auszulöschen.\n\nFür dieses besondere Ritual benötigen sie drei uralte Artefakte. Eines der Leere, eines des Sturms und eines des Meeres.\n\nIch kann selbst jetzt hören, wie das Relikt der Leere nach mir ruft. Es wird mit Energie verstärkt... oder verderbt. So genau kann ich es nicht sagen. Ich sehe es auf einer Klippe mit Blick über ein riesiges Meer.\n\nKommt, <Priester/Priesterin>, für einen solchen Schatz können wir eine viel bessere Verwendung finden.", sourceObjective = "Findet den Leerenstein in Drustvar.", progress = "So eine Abwechslung kann ganz belebend sein, oder, {name}?", completion = "Lasst Euch nicht ablenken. Es gibt noch viel für uns zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[54059] = { id = 54059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Nachtkriegerin", description = "Es scheint, als ob die Nachtelfen uns die Informationen nicht einfach so preisgeben werden, aber vielleicht wird das der Irrwisch, den Ihr gefangen habt.\n\nVersucht, ob Ihr ihn dazu bringen könnt, zu offenbaren, was hier an der Dunkelküste geschehen ist. Es ist mir egal, wie Ihr das anstellt.\n\nVater Norlath wird sich im Anschluss um den Irrwisch kümmern.", sourceObjective = "Sprecht mit dem verlorenen Irrwisch und findet heraus, warum der Mond sich verdunkelt hat.", progress = "Habt Ihr den Irrwisch zur Zusammenarbeit gebracht?", completion = "Sehr beunruhigend. Wir werden unsere Pläne beschleunigen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54060] = { id = 54060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
