quests[54082] = { id = 54082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Energie", description = "Willkommen zurück, liebes Versuchsobjekt.\n\nMeine geliebte Schwester hat mich freundlicherweise gebeten, das heutige Experiment durchzuführen, das etwas außerhalb unserer üblichen Legalitätsstandards liegt...\n\nIhr dürft Euch wie immer gegen eine Teilnahme entscheiden, dann werden wir für angemessene Ersatzversuchsobjekte sorgen.\n\nUnser neues Projekt benötigt mehr Energie, als unser Generator bereitstellen kann. Wir müssen ihn mit einer Energiespitze von außerhalb überladen.\n\nBondos Hof hat die beste Stromleitung in Mechagon, also werden wir das, was wir brauchen, von diesen Halunken abzwacken.", sourceObjective = "Verbindet die Stromleitung von Bondos Hof mit dem Blitzladelabor.", completion = "Unser Generator quillt geradezu über vor Energie... Ich habe mich noch niemals so lebendig gefühlt!", sourceObjectiveStatus = "unverified-source-field" }
quests[54083] = { id = 54083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gut schmieren, niemals verlieren", description = "Römms sagte, Ihr hättet daran gearbeitet, diese Mechaspinne wieder in Betrieb zu nehmen. Ich werde Euch doch nicht den ganzen Spaß überlassen!\n\nDieses rostige alte Ding wird eine Menge Schmierfett brauchen, um sich wieder in Bewegung zu setzen. Also habe ich notdürftig eine ganz spezielle Schmierfettfalle zusammengeschustert, die Euch helfen soll, Schmierfett von den Schleimen hier in der Nähe zu sammeln.", sourceObjective = "Benutzt die Schmierfettfalle, um 12 Zahnradschmierfett aus Schleimen im Auslass zu gewinnen.", completion = "Das war wirklich eine schmierige Angelegenheit. Zum Glück musste ich das nicht machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54085] = { id = 54085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zubehör nur getrennt erhältlich" }
quests[54086] = { id = 54086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der richtige Bot für den Job", description = "Hier wird nichts verschwendet. Jeder besiegte Bot bekommt eine zweite Chance!\n\nWenn ich diese Mechaspinne reparieren soll, werde ich ein paar zusätzliche Schraubbots benötigen, die mit mir zusammenarbeiten.\n\nBenutzt meinen Botneuauflader bei drei inaktiven Repetierschraubbots und bringt sie mir, damit sie für mich arbeiten können.", sourceObjective = "Bringt drei Repetierschraubbots zu Recycler Römms.", progress = "Habt Ihr die Repetierschraubbots schon gefunden?", completion = "Diese Bots werden rund um die Uhr daran arbeiten, dieses Reittier wieder auf Vordermann zu bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54087] = { id = 54087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mindestgröße einhalten!", description = "Der Moment ist gekommen, {name}.\n\nIch bin der Meinung, dass ein Gnom, zum Beispiel ich, bei solch einem historischen Ereignis derjenige sein sollte, der das Gerät aktiviert.\n\nLasst mich wissen, wann wir Eurer Meinung nach beginnen sollten.", sourceObjective = "Sagt Bescheid, wenn ich das Gerät aktivieren kann.", progress = "Das ist eine sehr wichtige Entdeckung!", completion = "Ich bin mir sicher, dass der König Euch nicht schaden wollte, Champion. Lasst Euch von diesem Vorfall nicht abschrecken. Ich brauche Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[54088] = { id = 54088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Legende von Mechagon", description = "Ich bin gekommen, sobald ich davon gehört habe! In Tiragarde wurde eine mysteriöse Kammer entdeckt.\n\nVor Jahrhunderten führte König Mechagon, der letzte König der Gnome, seine Anhänger auf der Suche nach einem mysteriösen Land der Technologie an. Er hat keine Hinweise hinterlassen, wo genau er gesucht hat, und über die Zeit geriet die Legende immer mehr in Vergessenheit. In dieser Kammer könnten wir dem wahren Schicksal von König Mechagon ein Stück näherkommen!\n\nIch muss das direkt untersuchen. Trefft mich dort, Champion. Ich könnte Eure Hilfe brauchen.", sourceObjective = "Trefft Tüftlermeister Oberfunks außerhalb der mysteriösen Kammer.", completion = "Das sieht sehr viel versprechend aus! Jetzt, da Ihr hier seid, können wir mit der Erkundung beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54089] = { id = 54089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omgar Unheilsbogen" }
quests[54090] = { id = 54090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spielzeuge der Zerstörung", description = "Ricket hat eine Botschaft geschickt, sie sei hier in Mechagon, also bin ich sofort hierhergeeilt, um bei der, äh... Forschung zu helfen.\n\nIch habe die Peons auf der gesamten Insel nach jeglicher Technologie suchen lassen, die sie auftreiben konnten. Mit dem Zeug, das wir hier haben, werden wir ein paar erstaunliche Waffen herstellen, um gegen König Mechagon zu kämpfen. Danach werden wir reich, wenn wir sie verkaufen!\n\nHelft mir dabei, die gesammelten Ideen aller in eine perfekte Waffe umzumünzen!", sourceObjective = "Helft Raketenchef Doppeldecker beim Bau der perfekten Waffe.", progress = "Habt Ihr schon eine erstaunliche Waffe gebaut?", completion = "So etwas Schönes muss einem guten Zweck zugeführt werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[54091] = { id = 54091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jörn Starkarm" }
quests[54094] = { id = 54094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Goblindefinition von Erfolg", description = "Ich bin hier so weit fertig. Ich werde noch ein bisschen mit dem Mech herumspielen. Dank Euch weiß ich jetzt ziemlich genau, wie er funktioniert.\n\nNathanos \"Prinz von Tod und Zerstörung\" Pestrufer wird Euch auf dem Kahn zurückerwarten. Wie hieß er doch gleich? Klageschrei oder so...\n\nEr wird sich freuen, wenn er erfährt, dass wir uns um alles gekümmert haben. Andererseits hab ich keine Ahnung, ob er sich überhaupt noch über irgendwas freut.", sourceObjective = "Trefft Euch mit Nathanos auf der Klagelied.", completion = "Gute Arbeit. Jetzt, wo wir wissen, dass unser Hauptvorrat Azerit in Sicherheit ist, können wir aufatmen.\n\nDie Dunkle Fürstin hat weitere Pläne, die Eurer Hilfe bedürfen. Wir haben eine vielversprechende Spur zu jemandem, der uns dabei helfen kann, Kul Tiras von innen heraus zu vernichten.\n\nSetzt inzwischen den Kampf gegen die Allianz fort. Wir können es uns nicht leisten, unvorsichtig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[54096] = { id = 54096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Untergang des Sonnenbrunnens", description = "Die Flamme der Laterne wird schwächer. Es ist Eure letzte Aufgabe, sie neu zu entfachen.\n\nUm das zu bewerkstelligen, müsst Ihr einen letzten Pfad beschreiten. Obwohl der Sonnenbrunnen wieder unter unserer Kontrolle steht, dürfen wie nie vergessen, dass er ein weiterer Teil von uns war, den Arthas uns genommen hat... Und diese Tatsache hat unseren verstorbenen Prinzen letztendlich dazu gezwungen, eine neue Lebensweise für uns zu finden.\n\nBetretet das Sonnenbrunnenplateau und werdet Zeuge seines Untergangs.", sourceObjective = "Schießt das Szenario \"Der Untergang des Sonnenbrunnens\" ab.", completion = "<Der Lordregent nimmt die Laterne von Euch entgegen.>\n \nEs ist vollbracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[54097] = { id = 54097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Dunkle Fürstin ruft", description = "Champion, die Dunkle Fürstin braucht Euch.\n\nWir können das hier nicht weiter besprechen. Brecht sofort auf nach Orgrimmar.\n\nLasst sie besser nicht warten.", sourceObjective = "Trefft Euch mit Fürstin Sylvanas Windläufer in Orgrimmar.", completion = "Meine Wachen sind an der Tür positioniert und stellen sicher, dass diese Unterhaltung unter uns bleibt.\n\nAlso, reden wir über Varok Saurfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[54099] = { id = 54099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hochfürst", description = "Ich habe Euch hergebeten, um eine wichtige Angelegenheit der Horde zu besprechen.\n\nVarok Saurfang ist nicht mehr in Sturmwind.\n\nLasst uns diese Wendung der Ereignisse diskutieren.", sourceObjective = "Besprecht das Schicksal von Saurfang mit Fürstin Sylvanas Windläufer in Orgrimmar.", completion = "Ich hoffe, Ihr versteht, wie überaus kritisch diese Situation ist, Champion.\n\nDie Allianz wird ihn sofort töten, wenn sie ihn erwischt. Von einigen Mitgliedern der Horde wird er als Verräter angesehen, seit er sich bei der Schlacht um Lordaeron ergeben wollte.\n\nEs liegt in Eurer Verantwortung, Varok Saurfang lebendig zu uns zurückzuschaffen. Seid so diskret wie möglich.", sourceObjectiveStatus = "unverified-source-field" }
quests[54100] = { id = 54100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alternativen finden", description = "Meine Spione berichten, dass unser Hochfürst nicht auf dieselbe Weise gegangen ist, wie er hereinkam. Wir haben ehrlich gesagt keine Ahnung, wie er entkommen konnte. Es gibt keine Spuren von ihm an den bekannten Ausgängen des Verlieses oder in der Kanalisation. Er ist einfach von einem Moment auf den anderen aus seiner Zelle verschwunden.\n\nBeginnt Eure Untersuchung in Sturmwind. Es muss einen weiteren Ausgang geben, den wir noch nicht entdeckt haben.\n\nDie Dunkle Waldläuferin Lyana wird Euch dort treffen. Ihre Fähigkeit, Spuren zu lesen, ist unerreicht.\n\nEnttäuscht mich nicht, mein Champion.", sourceObjective = "Trefft Euch mit der Dunklen Waldläuferin Lyana im Wald von Elwynn.", completion = "Wir haben keine Zeit zu verlieren. Beginnen wir mit unserer Untersuchung.", sourceObjectiveStatus = "unverified-source-field" }
quests[54101] = { id = 54101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Spur", description = "Bleibt in Deckung. Wir wollen hier draußen nicht erwischt werden.\n\nUnsere Spione beobachten Sturmwind Tag und Nacht und haben Saurfang nirgends gesehen.\n\nEs wurden auch keine auffällig großen Karren oder verdächtige Schiffe bei Nacht gesehen, falls Ihr daran dachtet.\n\nWie zum Henker ist er dann entkommen?\n\nSehen wir uns um.", sourceObjective = "Folgt der Spur von Varok Saurfang im Wald von Elwynn.", progress = "Untersuchen wir die Sache weiter.", completion = "Der SI:7 schleicht außerhalb von Sturmwind herum? Hmm, wahrscheinlich suchen die das Gleiche wie wir.\n\nWir müssen weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[54102] = { id = 54102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht gen Osten", description = "Spione vom SI:7 in Sturmwind zu sehen ist nicht unbedingt ungewöhnlich, aber trotzdem stimmt hier etwas nicht.\n\nWir müssen herausfinden, wo die Fährte von Saurfang weitergeht. Die letzten Spuren gingen Richtung Osten gen Rotkammgebirge.\n\nDer Weg zum Rotkammgebirge führt an Drei Ecken vorbei, einem der am besten verteidigten Türme der Allianz.\n\nIch habe eine Idee. Wir treffen uns dort.", sourceObjective = "Trefft die Dunkle Waldläuferin Lyana in den Drei Ecken im Rotkammgebirge.", completion = "Bis auf diesen hier gibt es nur wenige Pfade durch das Rotkammgebirge.\n\nWir sollten unsere Untersuchung hier fortsetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54103] = { id = 54103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Über drei Ecken", description = "Falls Saurfang diese Richtung eingeschlagen hat, wäre es schwierig für ihn gewesen, den Wachposten an den Drei Ecken zu entgehen.\n\nWir könnten einfach reingehen und fragen. Aber ich bezweifle ernsthaft, dass sie freiwillig mit Informationen rausrücken werden.\n\nWir brauchen also eine andere Lösung.\n\nIch habe diesen Trank von unseren Alchemisten besorgt. Er wird uns für einige Zeit in... igitt... Menschen verwandeln.\n\nSo können wir die Wachen problemlos befragen. Vielleicht hat ja jemand etwas gesehen.", sourceObjective = "Trinkt den Trank der Vermenschlichung und befragt die Einwohner des Rotkammgebirges.", progress = "Finden wir so viel heraus, wie wir können.", completion = "Hm, Shaw war also darin verwickelt? Schon wieder der SI:7...\n\nVielleicht ein Zufall, vielleicht auch nicht.\n\nWir haben kaum etwas, woran wir anknüpfen können. Gehen wir also davon aus, dass Saurfang Richtung Osten weitergegangen ist, abseits der Hauptpfade.", sourceObjectiveStatus = "unverified-source-field" }
quests[54104] = { id = 54104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spuren von Saurfang", description = "Mit betrunkenen Wachen auf den Posten und den anderen außer Reichweite wäre es für Saurfang ein Leichtes gewesen, unbemerkt die Drei Ecken zu passieren.\n\nDer Weg gabelt sich südlich der Stadt. Die kleineren Pfade im Rotkammgebirge werden kaum patrouilliert und wimmeln nur so von Gnollen und Spinnen. Mit anderen Worten sind sie also perfekt für einen Orc, der ungesehen reisen möchte.\n\nWahrscheinlich hat er den Uferpfad genommen. Wir sollten dort weitersuchen.", sourceObjective = "Folgt der Spur von Varok Saurfang im Rotkammgebirge.", progress = "Nun? Worauf wartet Ihr noch?", completion = "Nun, das war belebend. \n\nWenn man die Größe und die Wunden der Spinne betrachtet, würde ich meinen, dass wir uns auf der rechten Fährte befinden.\n\nIch weiß auch schon, wohin wir uns als Nächstes begeben sollten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54105] = { id = 54105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immer Richtung Osten", description = "Alles deutet klar darauf hin, dass sich unser Ziel Richtung Osten durchgeschlagen hat. \n\nIch bin mir nicht sicher, was dahinter steckt, doch ich habe schon einen Verdacht.\n\nIch werde mir den Bereich ein wenig aus der Luft ansehen. Treffen wir uns danach am Rotkammpass.", sourceObjective = "Findet die Dunkle Waldläuferin Lyana am Rotkammpass im Rotkammgebirge.", completion = "Dies ist einer der wenigen Pfade durch das Rotkammgebirge. Wenn Saurfang hier entlanggekommen ist, dann hat er diesen Weg genommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54106] = { id = 54106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hinweisen folgen", description = "Seht dort, unten am Hügel. Dort treibt sich ein Jäger der Allianz herum.\n\nNiemand kennt diese Pfade so gut wie sie. Wenn unser Ziel hier entlanggekommen ist, hätte der Jäger sicher seine Spuren gesehen. Seine Hunde könnten sogar Saurfangs Witterung aufgenommen haben.\n\nWir haben hier noch eine Dosis des Tranks. Befragen wir den hier, solange er noch allein ist.", sourceObjective = "Trinkt den Trank der Vermenschlichung und befragt Jäger McAlister am Rotkammpass im Rotkammgebirge.", completion = "Ich danke Euch für Eure Unterstützung bei dieser Untersuchung, Champion. Wir sind uns praktisch sicher, wo Saurfang sich befindet.\n\nBevor wir fortfahren können, muss ich dem Kriegshäuptling Bericht erstatten. Wir werden Euch herbeirufen, wenn wir erneut Eure Hilfe brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54107] = { id = 54107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finstere Kunde", description = "Hey, Mann, diese Dunkle Waldläuferin bindet Euch 'nen Bär'n auf!\n\nSaurfang wusste, dass die hinter ihm her sin'. Er wollte, dass ich den Pass bewach' un' rausfind, wer ihn umbring'n will. Soll versuch'n, ihn zu warnen, wenn's geht.\n\nDie wird gar nix bericht'n... die wird ihn töt'n. Hat wahrscheinlich 'nen Haufen Todeswachen, die nur auf ihr Zeich'n wart'n.\n\nWir müss'n die aufhalt'n! Seid Ihr dabei?", sourceObjective = "Trefft Euch mit Zekhan in den Sümpfen des Elends.", completion = "Zu spät! Die war'n schneller!", sourceObjectiveStatus = "unverified-source-field" }
quests[54108] = { id = 54108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tod eines Kriegers", description = "Sie wird versuch'n, ihn zu schnapp'n, un' dann seh'n wir Varok Saurfang nie wieder.\n\nDas war keine Rettungsmission, hier geht's nur um Macht un' Kontrolle. Sylvanas denkt, sie hätt' alle Karten in der Hand.\n\nAber mit uns hat sie nich' gerechnet!\n\nNa los!", sourceObjective = "Verteidigt Varok Saurfang in den Sümpfen des Elends.", progress = "Seid Ihr auf unsrer Seite?", completion = "Ich danke Euch und dem jungen Zekhan für die Unterstützung. Ich wusste, dass es nur eine Frage der Zeit sein würde, bis sie mich jagen lässt. \n\nVon diesem Vorhaben wird sie auch sicher nichts abbringen.\n\nIch möchte Euch um etwas bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54109] = { id = 54109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gunst der Königin", description = "Ich möchte Euch um zwei Dinge bitten und es fällt mir nicht leicht.\n\nErstens müsst Ihr die Gunst unseres Kriegshäuptlings bewahren. Sie wird zweifelsohne Fragen haben, die schon bald zu Misstrauen führen werden. Doch gerade jetzt darf sie Euch nicht als <Verbündeten/Verbündete> verlieren. Einen ihrer größten Champions würde sie nicht ohne Weiteres aufgeben wollen.\n\nDeshalb muss es den Schein haben, dass Ihr mich im Kampf gestellt habt und besiegt wurdet. Ich gehe davon aus, dass Ihr einen ordentlichen Schlag verkraften könnt.\n\nAls Zweites bitte ich Euch, mir nicht mehr zu folgen. Diese Reise muss ich allein beenden.", sourceObjective = "Lasst Euch von Varok Saurfang schlagen und erstattet dann Kriegshäuptling Sylvanas Windläufer in Orgrimmar Bericht.", completion = "Ich habe nichts mehr von Lyana gehört, seit ich sie auf ihre letzte Mission ausgesandt habe.\n\nSeid Ihr gekommen, um für sie Bericht zu erstatten?", sourceObjectiveStatus = "unverified-source-field" }
quests[54112] = { id = 54112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebelwirkerin Nian" }
quests[54113] = { id = 54113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder kleine Tod hilft", description = "<Das Flüstern ist erst kaum wahrnehmbar, aber wird lauter, während Ihr die Klinge in der Hand haltet.>\n\nSo schwach... brauche... Blut... Seelen...\n\n<Die Stimme wird wieder leiser, aber Ihr könnt immer noch spüren, wie der Dolch Euch antreiben will.>", sourceObjective = "Unterstützt Xal'atath bei der Erholung.", completion = "Ah... schon viel besser. Wie grausam von dem Priester, mich in einem solchen Zustand zu belassen!\n\nAber genug von mir. Ihr habt zweifelsohne eine Menge Fragen. Und ich biete unzählige Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54114] = { id = 54114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder kleine Tod hilft", description = "<Das Flüstern ist erst kaum wahrnehmbar, aber wird lauter, während Ihr die Klinge in der Hand haltet.>\n\nSo schwach... brauche... Blut... Seelen...\n\n<Die Stimme wird wieder leiser, aber Ihr könnt immer noch spüren, wie der Dolch Euch antreiben will.\n\nDas Gefühl kommt Euch vertraut vor.>", sourceObjective = "Unterstützt Xal'atath bei der Erholung.", completion = "Ah... schon viel besser. Wie grausam von Euch, mich in einem solchen Zustand zu belassen!\n\nAber wir können später in Erinnerungen schwelgen. Ihr habt zweifelsohne eine Menge Fragen. Und wie Ihr wisst, biete ich unzählige Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54117] = { id = 54117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder kleine Tod hilft", description = "<Das Flüstern ist erst kaum wahrnehmbar, aber wird lauter, während Ihr die Klinge in der Hand haltet.>\n\nSo schwach... brauche... Blut... Seelen...\n\n<Die Stimme wird wieder leiser, aber Ihr könnt immer noch spüren, wie der Dolch Euch antreiben will.>", sourceObjective = "Unterstützt Xal'atath bei der Erholung.", completion = "Ah... schon viel besser. Wie grausam von dem Priester, mich in einem solchen Zustand zu belassen!\n\nAber genug von mir. Ihr habt zweifelsohne eine Menge Fragen. Und ich biete unzählige Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54118] = { id = 54118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jeder kleine Tod hilft", description = "<Das Flüstern ist erst kaum wahrnehmbar, aber wird lauter, während Ihr die Klinge in der Hand haltet.>\n\nSo schwach... brauche... Blut... Seelen...\n\n<Die Stimme wird wieder leiser, aber Ihr könnt immer noch spüren, wie der Dolch Euch antreiben will.\n\nDas Gefühl kommt Euch vertraut vor.>", sourceObjective = "Unterstützt Xal'atath bei der Erholung.", completion = "Ah... schon viel besser. Wie grausam von Euch, mich in einem solchen Zustand zu belassen!\n\nAber wir können später in Erinnerungen schwelgen. Ihr habt zweifelsohne eine Menge Fragen. Und wie Ihr wisst, biete ich unzählige Antworten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54119] = { id = 54119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hartford Strengbach" }
quests[54120] = { id = 54120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Orgrimmar", description = "'ne Dunkelheit in meinem Geist verschleiert meine Erinnerung daran, was an dem Tag passiert is', an dem ich Sylvanas zum Kriegshäuptling ernannt hab.\n\nNehmt meine Gleve und geht zum Scheiterhauf'n in Orgrimmar, auf dem ich verbrannt wurde.\n\nMein alter Meister Gadrin hat genug Juju, um mich an den Ort zu ruf'n.\n\nGeht. Wir seh'n uns dort.", sourceObjective = "Nehmt Vol'jins Gleve und bringt sie Meister Gadrin bei der Blockade von Dranosh'ar in Durotar.\n\nBereitgestellter Gegenstand:", completion = "Vol'jin mag zwar meinem Können vertrau'n, aber ich hab 'n paar Verbündete zusammengeruf'n, die uns helf'n werd'n. Das wird nich' einfach. Talanji wäre besser für so 'n Ritual geeignet, aber ich werd mein Bestes tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[54121] = { id = 54121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aschenwinds Ausbruch", description = "Die Dunkle Fürstin würde gerne einen weiteren potentiellen Verbündeten im Kampf gegen die Allianz gewinnen.\n\nLady Aschenwind, Vorsitzende von Aschenwind & Co, war bis zu ihrer Gefangennahme einer der größten Feinde von Kul Tiras.\n\nWir werden sie befreien.\n\nTrefft Valtrois im Tiragardesund. Sie schmiedet gemeinsam mit Rexxar einen Plan zur Rettung von Aschenwind.", sourceObjective = "Trefft Euch mit Valtrois im Tiragardesund.", completion = "Ihr kommt gerade rechtzeitig. Wir haben viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[54123] = { id = 54123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das gehört in meinen Mech!", description = "Seht Euch das mal an! Meine neuste Schöpfung, die jemand anderes erdacht und gebaut hat: Gallywix' Mechaoberdampfhammer!\n\nIch habe ihn mit dem ganzen Azerit aufgetankt, das Ihr gefunden habt. Ich brauche aber noch ein wenig mehr, um ihm den Extra-Kick zu geben.\n\nEIGENTLICH sollte unser Unterfangen hier für das Zeug sorgen, aber es gibt da so einen Azeritmatsch, der Probleme verursacht!\n\nMein Junge Flick hat einen Azeritsauger gebastelt. Ich will, dass ihr das Azerit aus diesen Schleimen heraussaugt!", sourceObjective = "Holt mithilfe des AzeritvakuumierersAzerit aus den Azeritschleimen.", completion = "So gefällt mir das! Unser Prachtstück hier wird in null Komma nichts vollgetankt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54124] = { id = 54124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vermeidung von Zivilklagen für Anfänger", description = "Tach, {name}! Da verlasse ich mal für zwei Sekunden den A.M.O.D. und kümmere mich um den alten Gallywix und schon stehe ich bis zu den Knien in Azeritglibber!\n\nHört zu, Ihr müsst meine Goblins vor diesen Monstern retten.\n\nIch hab, um ehrlich zu sein, an der Versicherung gespart, was Verletzungen durch Azeritmonster angeht.\n\nNun schaut mich nicht so an! Wer konnte denn ahnen, dass diese Schleime auftauchen und die Jungs angreifen!\n\nTut mir den Gefallen und holt die Goblins da raus, okay?", sourceObjective = "Rettet 6 unversicherte Goblinarbeiter.", completion = "Ihr seid ein echter Lebensretter! Also für meine Arbeiter, für mich eher ein Goldretter.\n\nWenn jemand fragt, haben wir nie darüber gesprochen. Ihr wisst, was ich meine?", sourceObjectiveStatus = "unverified-source-field" }
quests[54126] = { id = 54126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Messer drehen", description = "Die Relikte gehören uns... so wie es sein sollte.\n\nEs fehlt nur noch ein Schritt, um die großen Wahrheiten zu offenbaren.\n\nDie Naga wollten ihren Sturm von einem Ort aus heraufbeschwören, an dem uralte Macht noch nachklingt. Dieser Ort hat im Laufe der Zeiten unzählige Namen erhalten, aber Ihr Sterblichen kennt ihn zumeist als Klippe des Vergessens.\n\nIch werde vorausgehen und mit den Vorbereitungen beginnen. Trefft mich dann dort.", sourceObjective = "Trefft Euch mit Xal'atath an der Klippe des Vergessens.", completion = "<Bruder Pike hört sich Eure Geschichte über Xal'atath und N'Zoth an.>\n\nDas sind wahrhaft finstere Neuigkeiten, {name}.\n\nIch habe gespürt, dass etwas unter den Wellen vor sich geht. Wenn der Alte Gott sich regt, müssen wir uns vorbereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54127] = { id = 54127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raketensprung", description = "Streitkräfte der Horde attackieren den Tiragardesund. Lasst sie jeden Schritt bereuen, den sie auf unser Land tun!", sourceObjective = "Schlagt die Streitkräfte der Horde zurück, die den Tiragardesund angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54128] = { id = 54128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notwendige Vorsichtsmaßnahmen", description = "Das war echt der Hammer! Wir haben Mekkadrills lächerliche kleine Armee noch weiter dezimiert.\n\nWir wissen jetzt, wo sich dieser kleine Nichtsnutz mit seinem Luftschiff versteckt. Von dort aus steuert er alle seine FRÜHEREN Mechs.\n\nDer Plan sieht so aus: Wir fliegen da rüber, jagen den Irren in die Luft und vernichten sein Luftschiff!\n\nAlso, ich bin kein Idiot, {name}, ich bin der cleverste Goblin, den es gibt. Vorher ergreifen wir das, was man notwendige Vorsichtsmaßnahmen nennt.\n\nNehmt dieses Handbuch, ich will, dass Ihr dafür sorgt, dass der G.M.O.D. betriebsbereit ist!", sourceObjective = "Überprüft die Systeme des G.M.O.D.", completion = "Ist mir egal, was die Anzeige sagt. Ich sage, wir sind bereit zum Aufbruch!", sourceObjectiveStatus = "unverified-source-field" }
quests[54129] = { id = 54129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erster Maat Malle" }
quests[54130] = { id = 54130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere neuen Freunde", description = "Ich hab gehört, dass die Allianz immer größer wird und immer mehr verschiedene Völker zusammenkommen, um gegen die gemeine Horde zu kämpfen.\n\nIch weiß nicht genau, wo die Botschaft ist, aber sie soll hier irgendwo in Sturmwind sein. Könnt Ihr mir sagen, wo die ist? Ich möchte all unsere neuen Freunde sehen!", sourceObjective = "Bringt Euer Menschenwaisenkind zur Botschaft von Sturmwind. Falls es nicht anwesend sein sollte, wenn Ihr ankommt, dann ruft es zu Euch.", completion = "Wir haben jetzt so viele neue Freunde in der Stadt! Ich hoffe, dass sie mit mir spielen möchten!", sourceObjectiveStatus = "unverified-source-field" }
quests[54132] = { id = 54132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horde aus Helden", description = "Die Allianz hat mit einem koordinierten Angriff gegen unsere Streitkräfte im Sturmsangtal begonnen. Greift die feindlichen Streitkräfte an und schlagt sie zurück!", sourceObjective = "Führt den Angriff der Horde im Sturmsangtal an.", completion = "Usha sprach in ihrem Bericht in höchsten Tönen über Eure Taten im Sturmsangtal. Da sie eigentlich jeden hasst, müsst ihr tatsächlich einiges geleistet haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54134] = { id = 54134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele gute Helden", description = "Die Allianz hat die Oberhand in Vol'dun. Wir schlagen jetzt zu! Ihr werdet unsere Truppen zum Sieg führen!", sourceObjective = "Führt den Angriff der Allianz auf Vol'dun an.", completion = "Ich wünschte, ich hätte die letzte Schlacht in Vol'dun mit eigenen Augen sehen können! Ich habe gehört, dass es unglaublich war... Hätten wir doch nur mehr Soldaten wie Euch, dann wäre dieser Krieg schon morgen vorüber.", sourceObjectiveStatus = "unverified-source-field" }
quests[54135] = { id = 54135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Volles Rohr ins Moor", description = "Armeen der Allianz land'n an der Küste von Nazmir. Jagt sie wieder raus aufs Meer. Zandalar gehört uns!", sourceObjective = "Schlagt die Streitkräfte der Allianz zurück, die Nazmir angreifen.", completion = "Danke, {name}. Wir dürf'n nicht zulass'n, dass uns irgendwer dieses Land abnimmt.\n\nWeder die Bluttrolle, noch die Allianz, noch irgendwelche Fremden.\n\nDieses Land gehört den Zandalari... un' der Horde. Für immer!", sourceObjectiveStatus = "unverified-source-field" }
quests[54136] = { id = 54136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch ins Marschland", description = "Die Allianz hat mit einem koordinierten Angriff gegen die Horde in Nazmir begonnen. Besiegt die feindlichen Streitkräfte und vertreibt sie!", sourceObjective = "Führt den Angriff der Allianz auf Nazmir an.", completion = "Nazmir sieht vielleicht nicht nach viel aus, aber jedes Gebiet, das wir kontrollieren, eröffnet uns neue strategische Möglichkeiten für die Zukunft.\n\nAußerdem habt Ihr, wie ich höre, ein gewaltiges Loch in die Flotte der Horde da draußen gerissen. Ha! Das allein war die Reise wert.", sourceObjectiveStatus = "unverified-source-field" }
quests[54137] = { id = 54137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In jeder finsteren Ecke", description = "Die Allianz hat in Drustvar noch nicht richtig Fuß fassen können. Wir werden das Land für die Horde erobern!", sourceObjective = "Führt den Angriff der Horde auf Drustvar an.", completion = "Wo immer die Allianz sich auch verbirgt... wir werden sie finden.\n\nIch bin froh, Rokhan und die Dunkelspeere auf unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54138] = { id = 54138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritualrandale", description = "Die Allianz hat mit einem Angriff auf das Herz des Zandalariimperiums begonnen. Besiegt die Horde in ihrem eigenen Territorium und zeigt ihnen unsere Macht!", sourceObjective = "Führt den Angriff der Allianz auf Zuldazar an.", completion = "Ich habe Magister Umbrics Bericht gelesen... Er ließ auf eine beeindruckende Leistung dort drüben schließen. Die Horde wird nun begreifen, dass unsere Mächte die ihren bei Weitem übersteigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54139] = { id = 54139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Krieg ist gekommen", description = "Wir müssen los, {name}. Wir haben erfahren, dass die Allianz über Nazmir gegen uns marschieren will.\n\nGeht zum Großen Siegel. König Rastakhan und Prinzessin Talanji arbeiten dort gerade einen Angriffsplan aus.\n\nIn einem könnt Ihr Euch sicher sein: Wir werden die Allianz vernichten. Es ist geradezu töricht, uns durch Nazmir hindurch anzugreifen.", sourceObjective = "Trefft Euch mit König Rastakhan im Großen Siegel.", completion = "Lasst uns geh'n. Wir ham keine Zeit zu verlier'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54140] = { id = 54140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marsch der Zandalari", description = "Es wird Zeit, dass die Allianz der geballte Zorn der Zandalari trifft. Durch Nazmir anzugreif'n is' purer Selbstmord.\n\nDie Flotte muss Bescheid bekomm', genau wie unsre Flieger und Krieger. Sie müss'n sofort nach Nazmir aufbrech'n.\n\nIch helf derweil unsren Streitkräften beim Bluttor. Hier habt Ihr 'ne Liste derjenigen, mit denen Ihr sprech'n müsst, um unsre Armee zu mobilisier'n.\n\nGeht, so schnell Ihr könnt. Die Allianz muss unverzüglich aufgehalt'n werd'n.", sourceObjective = "Mobilisiert die Flotte, die Krieger und die Flieger der Zandalari.", completion = "Die Zandalari un' die Horde greif'n die Allianz an. Wir müssen uns beeil'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[54141] = { id = 54141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon von Azshara", description = "<Bei der Nagaleiche findet Ihr eine verzierte Metallscheibe. Die Schrift darauf ähnelt jener der Elfen, aber Ihr könnt sie nicht entziffern. Ihr vermutet, dass es sich um Nazjanisch handelt.\n\nVielleicht kann jemand, der sich mit den Artefakten der Naga auskennt, die Inschrift übersetzen.>", sourceObjective = "Bringt das Medaillon zu Sammler Kojo.", completion = "Ein Medaillon, sagt Ihr? Dann sehen wir uns das gleich mal an.\n\nIch hab schließlich nicht den ganzen Tag Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54143] = { id = 54143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vogelperspektive" }
quests[54144] = { id = 54144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Azshara", description = "<Kojo untersucht das Medaillon und verzieht das Gesicht.>\n\nIgitt... Naga.\n\nDas sind Befehle auf diesem Medaillon. Den Naga wurde befohlen, über unsere Küsten herzufallen und nach mächtigen Artefakten zu suchen.\n\nIch habe vor Kurzem solch ein Objekt gefunden. Seht Ihr den unheimlichen Dolch da drüben? Mir gruselt davor. Ich könnte schwören, dass er mir etwas zuflüstert.\n\nIch habe ihn auf einer Insel im Sturmsangtal gefunden, auf einem behelfsmäßigen Altar. Wenn Ihr ihn dort hinbringt, erhaltet Ihr vielleicht Hinweise darauf, was die Naga damit vorhatten.", sourceObjective = "Bringt den Dolch zum behelfsmäßigen Altar.", progress = "<Als Ihr den Dolch auf dem Altar ablegt, scheint er zu zittern und Euch anzublinzeln.>", completion = "<Ihr werdet von Schrecken und einer angstvollen Vorahnung erfüllt.\n\nMöglicherweise ist dies eine ganz schlechte Idee.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54145] = { id = 54145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Loa des Todes", description = "Bwonsamdi is' 'n gefährlicher Loa, aber nich' mal ich glaube, dass er zu Vol'jin auf seinem Totenbett gesproch'n hat. Sylvanas zu ernenn', klingt, nun... Er is' jedenfalls kein Unterstützer des Untods. Und wie ich den Kriegshäuptling einschätz', mag sie ihrerseits den Tod auch nich' gerade.\n\nWir müssen Bwonsamdi Respekt zoll'n, wenn wir mit ihm sprech'n, oder es wird was Schlimmes passier'n. Kommt, bleibt nah bei mir.", sourceObjective = "Stellt Bwonsamdi.", completion = "Jetz' hört ma' gut zu, Mann. Normalerweise würd'n Eure respektlosen Taten den alt'n Bwonsamdi ziemlich auf die Palme bring'n. Aber diesmal werd' ich es durchgeh'n lass'n... zumindest fürs Erste.\n\nWas Ihr da erzählt, klingt nach richtig üblem Mojo. Ihr werdet noch mehr drüber rausfind'n müss'n, von ein paar meiner... \"alt'n Freunde\".", sourceObjectiveStatus = "unverified-source-field" }
quests[54146] = { id = 54146, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starke neue Verbündete", description = "Ich hab gehört, wie ein paar Abenteurer gesagt haben, dass es neue Mitglieder der Horde gibt, die ganz anders als die anderen sein sollen! Und die sind sogar genau hier in Orgrimmar!\n\nIch weiß nicht, wo die Botschaft ist. Aber Ihr wisst das doch bestimmt? Könnt Ihr mich dort hinbringen? Da sollen sogar Orcs von einem anderen Planeten sein!", sourceObjective = "Bringt Euer Orcwaisenkind zur Botschaft von Orgrimmar. Falls es nicht anwesend sein sollte, wenn Ihr ankommt, dann ruft es zu Euch.", progress = "Neue Freunde in Orgrimmar! Jetzt kann ich immer hierher zurückkommen und sie besuchen.", completion = "Unsere neuen Freunde sind so toll! Ich freue mich schon darauf, immer hierher zurückkommen und sie oft zu besuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54147] = { id = 54147, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Val'kyr konfrontieren", description = "Vol'jins Geist gewinnt immer mehr an Kraft. Ich denk, wir brauch'n kein Ritual mehr, um ihn hier zu halt'n.\n\nDas is' auch gut so, weil Bwonsamdi mich gewarnt hat, dass Eyir über meine Anwesenheit wahrscheinlich nich' gerade erfreut sein wird. Anscheinend ham sie un' Bwonsamdi 'ne gemeinsame Vergangenheit, über die der Loa nich' red'n wollte.\n\nWir könn' fortfahr'n, wenn Ihr bereit seid.", sourceObjective = "Eskortiert den Geist von Vol'jin zu Eyir.", completion = "Ah... Eyir. Sie is' voller Wut un' Stolz un' weigert sich schon seit Jahrhunderten, mit mir zu red'n. Der hätte ich zugetraut, hinter Vol'jins Rückkehr zu steck'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54154] = { id = 54154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hügel der lugenden Augen" }
quests[54156] = { id = 54156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein blutiger Pfad", description = "Die Hauptflotte der Allianz un' der Kul Tiraner liegt vor der Küste in Nazmir. Aber wir könn' die Streitkräfte hier nich' ignorier'n.\n\nAnscheinend weht 'n komischer Nebel von Nazmir rüber. Die Kul Tiraner ham wohl irgend'nen Voodoo benutzt, um uns zu schwäch'n.\n\nWir werd'n 'nen blutigen Pfad durch die Narren der Allianz mäh'n. Helft unsern Streitkräften un' schwächt die Allianz.", sourceObjective = "Tötet 15 Soldaten der Allianz am Bluttor.", completion = "Also gut, meine Leute komm' mit dem Rest klar. Ihr müsst weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[54157] = { id = 54157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand wird zurückgelassen", description = "Die Krieger hier erzähl'n, dass Rokhan heldenhaft die Stellung gehalt'n hat. Er hat die Allianz un' ihre Champions aufgehalt'n, bis er besiegt wurde.\n\nRokhan is' immer noch hier irgendwo am Bluttor un' wird von 'ner seltsamen \"lichtgeschmiedeten\" Kreatur gefangen gehalt'n.\nIch muss hierbleib'n un' dabei helf'n, die Stellung zu halt'n. Ihr müsst Rokhan für mich rett'n!", sourceObjective = "Rettet Rokhan.", completion = "Danke, {name}. Rokhan wird sich in unsrem Kampf geg'n die Allianz als wertvoll erweis'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54161] = { id = 54161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wissen der Drust", description = "Bal'a dash, {name}.\n\nWenn Ihr einen Moment Zeit habt, könnte ich Eure Hilfe brauchen. Ich habe vor Kurzem eine Lieferung Drustrelikte erhalten, die aus Kul Tiras herausgeschmuggelt wurden.\n\nDie meisten davon weisen unsere üblichen Verzauberungen auf, aber eines davon ist einzigartig. Allein schon wenn ich es halte, bekomme ich eine Gänsehaut.\n\nIhr seid <mein bester Schüler/meine beste Schülerin> und vielleicht wäre es ja ganz erhellend, wenn wir es zusammen entzaubern, um zu sehen, wie es erschaffen wurde.\n\nWas meint Ihr dazu?", sourceObjective = "Entfernt vorsichtig die Verzauberung von dem uralten Drustrelikt, um seine Beschaffenheit zu ermitteln.", completion = "Tut mir leid, {name}, ich hätte nicht gedacht, dass die Verzauberung so komplex ist. Ich dachte, ich könnte die Zauberformel bewahren.\n\n\n\nDas war's dann wohl. Durch die Zerstörung des Reliktes wird uns die Formel dahinter verborgen bleiben.\n\nDas ist wirklich eine Schande. Es kommt nicht oft vor, dass ein anderer Verzauberer mich so blöd aussehen lässt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54162] = { id = 54162, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Harte Landung" }
quests[54163] = { id = 54163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Staub legt sich", description = "Wir haben einen großen Sieg errungen, {name}, wenn auch einen teuer erkauften.\n\nKönig Wrynn versammelt die Anführer der Allianz auf dem Platz der Einheit, um alles zu besprechen. Er hat auch um unsere Anwesenheit gebeten. \n\nGeht zum Platz der Einheit. Ich stoße dort in Kürze zu Euch.", sourceObjective = "Trefft Euch mit Anduin Wrynn auf dem Platz der Einheit.", completion = "Danke, dass Ihr gekommen seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54164] = { id = 54164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Tod des Königs", description = "König Rastakhan ist tot, die Flotte der Zandalari wurde dezimiert und wir haben viele wertvolle Soldaten verloren.\n\nDie Dunkle Fürstin ist auf dem Weg von Orgrimmar hierher, um die Lage zu beurteilen. Wir brauchen einen guten Plan für unsere nächste Aktion, bevor die Allianz wieder zuschlägt.\n\nAber zuerst werden wir dem gefallenen König unseren Respekt erweisen, wie es Tradition ist. Danach planen wir unsere nächsten Schritte.", sourceObjective = "Erweist König Rastakhan die letzte Ehre.", completion = "Gut, Ihr seid alle hier. Beginnen wir die Besprechung.", sourceObjectiveStatus = "unverified-source-field" }
quests[54165] = { id = 54165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rückkehr von Derek Prachtmeer", description = "Ich muss zugeben, ich hätte nicht gedacht, dass der kleine Löwe fähig ist, König Rastakhan zu töten. Blut wurde vergossen und Rache muss folgen.\n\nGebt mir einen Moment, den Toten zu ehren, und kommt dann mit mir. Es muss noch viel getan werden, um diesen Krieg zu gewinnen.", sourceObjective = "Wohnt Sylvanas' Besprechung mit Prinzessin Talanji bei.", completion = "Derek Prachtmeer wird verderbt werden und eine mächtige Waffe gegen Katherine und Jaina Prachtmeer darstellen.\n\nDie Allianz hat eine Armee geschickt, um Rastakhan zu töten. Wir werden nur einen einzigen Verlassenen brauchen, um ihre Anführer zu töten.\n\nIch werde Euch benachrichtigen, wenn ich Eure Hilfe wieder benötige. Kämpft in der Zwischenzeit weiter gegen die Allianz. Wir müssen überleben, bis unser Plan zur Ausführung bereit ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[54166] = { id = 54166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segel setzen", description = "Unterstützt die Horde, indem Ihr auf Inselexpeditionen Azerit sammelt.", sourceObjective = "Sammelt Azerit auf Inselexpeditionen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54167] = { id = 54167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segel setzen", description = "Unterstützt die Allianz, indem Ihr auf Inselexpeditionen Azerit sammelt.", sourceObjective = "Sammelt Azerit auf Inselexpeditionen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54169] = { id = 54169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatzkammerjäger", description = "Das Abyssische Szepter ist ein mächtiges Artefakt der Gezeitenweisen und eine ernsthafte Bedrohung für die Flotte. Die Horde hat es gestohlen, aber es wird in der Schatzkammer der Zandalari aufbewahrt.\n\nDie Sturmwacht hat eine Kopie des Szepters angefertigt. Eure erste Aufgabe ist, das echte Szepter zu beschaffen, ohne Verdacht zu erregen.\n\nKommt zu mir, wenn Ihr bereit seid, den Plan zu besprechen.", sourceObjective = "Holt das Abyssische Szepter aus der Schatzkammer der Zandalari.", completion = "Die Mission war ein Erfolg auf ganzer Linie, wie es scheint. Ich werde dafür sorgen, dass der Hochtüftler die Informationen bekommt, die Ihr gesammelt habt.\n\nSchon als ich jung war, habe ich viele Geschichten über das Abyssische Szepter gehört. Es ist nicht nur ein taktischer Sieg für uns, sondern auch gut für unsere Moral, das Relikt wieder in unseren Händen zu haben. Ich danke Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54170] = { id = 54170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ormin Raketenklaps" }
quests[54171] = { id = 54171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Abyssische Szepter", description = "Die Lordadmiralin hat einen Vorschlag für unseren nächsten Schachzug. Die Horde wird ganz sicher nicht damit rechnen, aber es ist gefährlich. Wir werden das Abyssische Szepter zurückstehlen.\n\nEuer Name wurde genannt, als es darum ging, wer diesen Plan ausführen kann. Ich hoffe, Ihr seid gewillt, diese Chance zu ergreifen.\n\nTrefft Lady Jaina in unserer Basis in Xibala. Sie hat dort weitere Informationen für Euch.", sourceObjective = "Trefft Euch mit Jaina Prachtmeer in Xibala in Zuldazar.", completion = "<Jaina schaut von ihrer Unterredung mit Magister Umbric auf, als Ihr Euch nähert.>\n\nDiese Mission wird gefährlich, aber sie ist notwendig, um den Grundstein für unseren Sieg hier in Zandalar zu legen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54172] = { id = 54172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Medaillon von Azshara", description = "<Bei der Nagaleiche findet Ihr eine verzierte Metallscheibe. Die Schrift darauf ähnelt jener der Elfen, aber Ihr könnt sie nicht entziffern. Ihr vermutet, dass es sich um Nazjanisch handelt.\n\nVielleicht kann jemand, der sich mit den Artefakten der Naga auskennt, die Inschrift übersetzen.>", sourceObjective = "Bringt das Medaillon zu Sammler Kojo.", completion = "Ein Medaillon, sagt Ihr? Dann sehen wir uns das gleich mal an.\n\nIch hab schließlich nicht den ganzen Tag Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54174] = { id = 54174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Azshara", description = "<Kojo untersucht das Medaillon und verzieht das Gesicht.>\n\nArgh... diese Naga.\n\nDas sind Befehle auf diesem Medaillon. Den Naga wurde befohlen, über unsere Küsten herzufallen und nach mächtigen Artefakten zu suchen.\n\nIch habe vor Kurzem solch ein Objekt gefunden. Seht Ihr den unheimlichen Dolch da drüben? Mir gruselt davor. Ich könnte schwören, dass er mir etwas zuflüstert.\n\nIch habe ihn ganz in der Nähe gefunden, in Atal'Gral, auf einem behelfsmäßigen Altar. Wenn Ihr ihn dort hinbringt, erhaltet Ihr vielleicht Hinweise darauf, was die Naga damit vorhatten.", sourceObjective = "Bringt den Dolch zum behelfsmäßigen Altar.", progress = "<Als Ihr den Dolch auf dem Altar ablegt, scheint er zu zittern und Euch anzublinzeln.>", completion = "<Ihr werdet von Schrecken und einer angstvollen Vorahnung erfüllt.\n\nMöglicherweise ist dies eine ganz schlechte Idee.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54175] = { id = 54175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stellt Euch Eurem Feind", description = "Wir haben beschlossen, dass wir am besten als Prachtmeersoldaten verkleidet in das Gefängnis eindringen. Rexxar wird unser Gefangener sein.\n\nWir dürfen kein Aufsehen erregen, bevor wir Aschenwind befreien.\n\nGrundsätzlich mache ich mich in solchen Vorhaben am besten, wenn ich über das richtige Referenzmaterial verfüge.\n\nIch habe einige Menschen ausgesucht, die mich interessieren. Ich möchte ihre Gesichter untersuchen.\n\nWendet den Splitter von Vesara auf sie an. Das wird sie dazu... ermutigen, mich aufzusuchen.", sourceObjective = "Schickt die von Valtrois ausgewählten Ziele zur Untersuchung zurück.", completion = "Menschen können so formbar sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[54176] = { id = 54176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Uniform gebracht", description = "Geht in die Gießerei. Die Prachtmeerwache hat dort übernommen. Sie werden uns mit hervorragenden Accessoires für unsere Verkleidung versorgen.\n\nIch kann ihre Gesichter nachbilden, aber ohne die richtige Kleidung kommen wir nicht weit.\n\nSammelt also genug Kleidung für uns.\n\nWir brauchen auch unbedingt den Übermantel der Kapitänin. \n\nWenn wir mit einem höheren Rang am Tor ankommen, wird es weniger Probleme geben.", sourceObjective = "Sammelt Ausrüstungsgegenstände von Prachtmeers Truppen in der Gießerei.", progress = "War die Ernte erfolgreich?", completion = "Gut gemacht, {name}. Das läuft besser, als erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[54177] = { id = 54177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine brillante Ablenkung", description = "Beim Betreten von Tol Dagor wollen wir vorsichtig sein.\n\nAber ich kann mir vorstellen, dass unser Abgang nicht so... diskret ablaufen wird.\n\nDie Gießerei im Westen soll früher Sprengstoff auf Azeritbasis hergestellt haben.\n\nNehmt Euch ein bisschen davon mit. Wir werden ihn brauchen können.", sourceObjective = "Besorgt das instabile Azerit.", progress = "Habt Ihr sie alle gefunden?", completion = "Ganz vorsichtig...\n\nVielleicht sollte sich Valtrois darum kümmern. Vielleicht kann sie es auf andere Art stabilisieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[54178] = { id = 54178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mitfahrgelegenheit", description = "Nathanos müsste mittlerweile ein Boot gefunden haben.\n\nWir sollten uns schleunigst mit ihm im Hafen treffen.\n\nEs ist unabdingbar, dass wir uns zügig um diese Angelegenheit kümmern.\n\nAuf uns warten bessere Möglichkeiten, wie wir den Vorstoß der Horde hier unterstützen können.", sourceObjective = "Findet Nathanos bei den Docks in Raubhafen.", completion = "Das sollte ausreichen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54179] = { id = 54179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch die Vordertür", description = "Wir müssen die Risiken Eurer Mission zur Rettung von Priscilla Aschenwind so gering wie möglich halten.\n\nIhr werdet während des Schichtwechsels an den Docks ankommen. Dort könnt Ihr Euch vorbereiten und dann das Gefängnis betreten. \n\nSucht mich in Zuldazar auf, wenn Ihr erfolgreich wart.", sourceObjective = "Schließt \"Flucht aus Tol Dagor\" ab.", completion = "Euer Erfolg ist ein gutes Zeichen für unsere zukünftigen Vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54180] = { id = 54180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quest" }
quests[54182] = { id = 54182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bilgewässer Prügelbrüder" }
quests[54183] = { id = 54183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kursbestimmung", description = "Ich habe zwar Bedenken, kann aber unsere Tapferkeit, unser Heldentum und die gebrachten Opfer nicht von der Hand weisen. Die von Euch gebrachten Opfer, {name}. Danke für all die Hilfe, die Ihr der Allianz gewährt habt.\n\nDie Zukunft unserer fortwährenden Kriegskampagne ist der Grund, aus dem ich alle hergebeten habe. Ich möchte, dass wir uns ansehen, was wir bisher getan haben, damit wir die beste Strategie für die Zukunft entwickeln können.", sourceObjective = "Wohnt der Diskussion am Platz der Einheit bei.", completion = "Wir mögen kurz vor dem Sieg stehen, aber wir dürfen nicht vergessen, wer wir sind. Denn sonst verlieren wir das, was uns am wichtigsten ist, und unser Sieg wird umsonst gewesen sein.\n\nIch hoffe, es stimmt, was Hochkommandant Wyrmbann und Meister Shaw sagen, und dass wir bald das Ende dieses Krieges sehen. Dann... können wir mit dem Wiederaufbau und der Heilung beginnen, für uns selbst, für Azeroth und für die Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[54184] = { id = 54184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Gnomeregan", description = "In Gnomeregan gab es in letzter Zeit ungewöhnliche Verbrauchsspitzen in der Stromversorgung. Ihr müsst so schnell wie möglich herausfinden, was da los ist.\n\nEiner der obersten Ingenieure, der für den reibungslosen Betrieb in Gnomeregan verantwortlich ist, hat angeboten, uns zu helfen, hineinzukommen und nach dem Rechten zu sehen.", sourceObjective = "Sucht Mikrozoox außerhalb von Gnomeregan in Dun Morogh.", completion = "Das ist doch nicht möglich! Was geht da drin nur vor?! Ich habe keine Zeit, Eure Fragen zu beantworten oder Euch banale Aufgaben zu geben. Es gibt hier wichtige Dinge zu tun!\n\nOh, Ihr wollt nach Gnomeregan hinein und herausfinden, was dort los ist? Warum sagt Ihr das nicht gleich?", sourceObjectiveStatus = "unverified-source-field" }
quests[54185] = { id = 54185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnomeregans neue Wächter", description = "Mein eigens modifiziertes Chaoserkennungsgerät liefert mir seit ein paar Tagen Werte außerhalb der Skala. Ihr denkt vielleicht, dass es kaum einen Unterschied zwischen Chaos und Gnomeregan gibt, und da habt Ihr teilweise auch recht, aber diese Werte sind so unglaublich hoch! So etwas habe ich noch nie gesehen!\n\nIch bin mir nicht sicher, was in Gnomeregan gerade passiert, aber irgendetwas ist anders. Wenn Ihr mutig genug seid, kann ich Euch tief nach Gnomeregan hineinteleportieren und Ihr könnt Euch selbst ein Bild machen.\n\nSagt Bescheid, wenn Ihr bereit seid.", sourceObjective = "Besiegt den Pulverisierbot Mk 6001 in Gnomeregan.", completion = "Jemand hat einen Bauplan von einer von Thermadrahts Erfindungen gestohlen? Das ist nicht gut. Wir haben erfahren, dass eine übel gesinnte Gruppe auch aus den Höhlen des Wehklagens und den Todesminen verschiedene Teile gesammelt hat. Was für einen Wahnsinn führen sie wohl im Schilde? Wer sind sie? Wir brauchen Antworten... schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[54186] = { id = 54186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierkampfherausforderung: Gnomeregan", description = "In Gnomeregan ist mal wieder die Hölle los. Diese Maschinen geben einfach nicht auf und kommen immer wieder.\n\nIch kann uns wieder dort hinein teleportieren, aber diese ganzen wildgewordenen Maschinen sind wieder da. Seid Ihr sicher, dass Ihr das wirklich wollt? Ich jedenfalls nicht. Ich meine, möglicherweise würde es mir gefallen, zuzuschauen, wie sich diese Blechbüchsen gegenseitig eins auf die Mütze geben. Ach, wisst Ihr was? Ihr kommt da schon zurecht. Auf geht's!", sourceObjective = "Besiegt den Pulverisierbot Mk 6001 in Gnomeregan.", completion = "Jemand hat einen Bauplan von einer von Thermadrahts Erfindungen gestohlen? Das ist nicht gut. Wir haben erfahren, dass eine übel gesinnte Gruppe auch aus den Höhlen des Wehklagens und den Todesminen verschiedene Teile gesammelt hat. Was für einen Wahnsinn führen sie wohl im Schilde? Wer sind sie? Wir brauchen Antworten... schnell.", sourceObjectiveStatus = "unverified-source-field" }
quests[54187] = { id = 54187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tee für zwei" }
quests[54188] = { id = 54188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botstörung" }
quests[54189] = { id = 54189, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wüstenkriecherei" }
quests[54190] = { id = 54190, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tee für zwei" }
quests[54191] = { id = 54191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kursänderung", description = "Champion, nun heißt es handeln.\n\nEs sind Entwicklungen im Gange, die für den Ausgang des Krieges entscheidend sein werden.\n\nMeldet Euch bei mir an Bord der Erlösenden Winde, sobald Ihr könnt.", sourceObjective = "Meldet Euch bei Halford Wyrmbann auf der Erlösenden Winde im Hafen von Boralus.", completion = "Ich habe Neuigkeiten von unseren Verbündeten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54192] = { id = 54192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heikle Informationen", description = "Ich habe einen Bericht von Kelsey Stahlfunken erhalten. Sie behauptet, dass sie etwas gefunden hat, das uns im Krieg helfen kann.\n\nSie wollte aber keine Details nennen, weil sie meinte, so eine wichtige Sache muss absolut geheim bleiben.\n\nEs sieht so aus, als ob Ihr persönlich mit ihr reden müsst.\n\nSie erwartet Euch in Xibala.", sourceObjective = "Trefft Euch mit Kelsey Stahlfunken in Zuldazar.", completion = "Nehmt Euch einen Moment, um Euch vorzubereiten. Ich habe atemberaubende Neuigkeiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[54193] = { id = 54193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das ist riesig!", sourceObjective = "Hört Euch Megs' und Mortens Plan an.", progress = "Wartet, bis Ihr von ihrem großen Plan erfahrt. Er ist perfekt!", completion = "Wisst Ihr jetzt Bescheid?", sourceObjectiveStatus = "unverified-source-field" }
quests[54194] = { id = 54194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wahrlich große Macht", description = "An der Außenverkleidung des Großmachers arbeiten wir noch, aber zuerst müssen wir sein Innenleben testen. Dort liegt seine eigentliche Macht!\n\nDie Großmachertechnologie ist der Horde um Jahre voraus, aber das Gerät ist trotzdem so einfach konstruiert, dass sogar ein Orc es bedienen kann!\n\nEinfach auf etwas zielen und aktivieren!", sourceObjective = "Testet den Großmacher an einer Kul Tiranischen Glucke.", completion = "Ich dachte mir schon, dass so etwas passieren würde.\n\nDer Geist der armen Glucke war nicht stark genug, um die Auswirkungen des Großmachers auszuhalten. Ansonsten lief aber alles wie geplant!", sourceObjectiveStatus = "unverified-source-field" }
quests[54195] = { id = 54195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Wildtier mit Grips", description = "Um optimale Ergebnisse zu erzielen, sollte der Großmacher bei jemandem von beträchtlicher Intelligenz eingesetzt werden. \n\nZum Glück gehört unser Partner der Kategorie Intelligenzbestie an. \n\nEr und sein Volk wurden von Kaja'mit ermächtigt. Es hat ihnen überragende Intelligenz verliehen! \n\nGeht zur Schlucht hinauf und gebt Grong Bescheid, dass wir mit dem Großmachen beginnen können!", sourceObjective = "Findet Grong im Gorillagraben.", completion = "Es ist also endlich so weit! \n\nIch warte schon lange auf diesen Tag: den Tag, an dem meine Ideen zum Leben erwachen!\n\nZuerst muss ich aber dafür sorgen, dass die Schlucht nach meiner Abreise sicher ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[54196] = { id = 54196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine andere Option", sourceObjective = "Tötet 12 Bilgewassergoblins im Gorillagraben.", completion = "Eine wahre Schande, dass wir zu solch roher Gewalt greifen mussten, aber es blieb uns keine Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[54197] = { id = 54197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für die Da'kani", description = "Habt Ihr die barbarischen Umstände gesehen, unter denen die Da'kani gefangen gehalten werden? Eingezäunt und eingekerkert warten sie darauf, abgeschlachtet zu werden oder Schlimmeres...\n\nIch kann nicht guten Gewissens von hier aufbrechen ohne die Gewissheit, dass meine Brüder befreit wurden.", sourceObjective = "Befreit 8 Lackaffen der Da'kani im Gorillagraben.", completion = "Ihr seid den Da'kani ein wahrer Freund!", sourceObjectiveStatus = "unverified-source-field" }
quests[54198] = { id = 54198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bittersüßer Abschied", description = "Ihr habt mir geholfen, mein Dorf auf meinen Abschied vorzubereiten. Nun muss ich mich selbst vorbereiten. \n\nTrefft mich in der Grotte, wo ich mich verabschieden werde.", sourceObjective = "Trefft Grong in Grongs Grotte.", completion = "Ich bin bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54199] = { id = 54199, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wohl der Vielen", sourceObjective = "Begleitet Grong nach Xibala.", completion = "Ihr habt mich nicht enttäuscht, {name}. Grong ist die Antwort auf all unsere Probleme! \n\nEr muss lediglich diesen Stapel von Dokumenten unterschreiben, bevor wir beginnen. Das ist reine Routine, glaubt mir.", sourceObjectiveStatus = "unverified-source-field" }
quests[54200] = { id = 54200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grundlegende Aufgaben", description = "Bevor wir den Großmacher verwenden, müssen wir ein paar Grundwerte erfassen.\n\nGrong wird ein paar Testaufgaben erfüllen, bei denen es um Geschwindigkeit, Intelligenz und Stärke geht. \n\nDas wird uns helfen, die Steigerung seiner Fähigkeiten genau zu messen, sobald er großgemacht wurde.", sourceObjective = "Helft dabei, Grundwerte über Grongs Geschwindigkeit, Intelligenz und Stärke zu sammeln.", completion = "Sehr beeindruckend, wirklich! Grong ist großartig in Form.", sourceObjectiveStatus = "unverified-source-field" }
quests[54201] = { id = 54201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grongs Größe", description = "Grong ist an sich schon beeindruckend groß. So groß, dass ich glaube, dass unser Großmacher ohne kleine Modifikationen nicht um seine Birne passen wird.\n\nIch brauche ein bisschen Erz, um die erforderlichen Anpassungen zu machen. Da trifft es sich doch gut, dass Goblins in der Nähe schon Erz abgebaut haben. Wir müssen es ihnen einfach nur abnehmen!\n\nBeschafft uns eine ausreichende Menge azeritdurchströmtes Erz und wir sind wieder im Geschäft!", sourceObjective = "Beschafft 12 Stücke azeritdurchströmtes Erz.", progress = "Habt Ihr das Erz sammeln können?", completion = "Das sollte sicherstellen, dass der Großmacher auch passt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54202] = { id = 54202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kernkalibrierung", description = "Der Großmacher ist so gut wie fertig! Jetzt muss nur noch der Kern kalibriert werden. \n\nUm katastrophale Ergebnisse zu vermeiden, sollten wir das Gerät nur an Dingen ausprobieren, die bereits tot sind.\n\nDas ist keine schwere Aufgabe!\n\nIch habe das Gefühl, dass es für Euch kein Problem sein wird, geeignete Objekte in den benötigten Zustand zu überführen.", sourceObjective = "Kalibriert den Kern des Großmachers, indem Ihr ihn an toten Objekten in der Bilgewasserbonanza testet.", completion = "Ist die Kalibrierung abgeschlossen? Fabelhaft!", sourceObjectiveStatus = "unverified-source-field" }
quests[54203] = { id = 54203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Großmachung", description = "Ich erkläre Euch kurz, wie's läuft, bevor wir loslegen.\n\nDer Großmacher wird ferngesteuert. \n\nSeht Ihr diesen großen roten Knopf?\n\n<Megs deutet auf das Gerät in ihrer Hand.> \n\nDas schockt den Träger ordentlich mit einer Machtwelle und macht ihn größer.\n\nZur Sicherheit solltet Ihr hier im Lager bleiben. \n\nIch glaube, das war's! Bereit für ein bisschen Wissenschaft?", sourceObjective = "Testet Grongs Werte, während er großgemacht ist.", completion = "Grong hat unsere Erwartungen bei Weitem übertroffen. Ich würde sagen, das ist ein durchschlagender Erfolg.", sourceObjectiveStatus = "unverified-source-field" }
quests[54204] = { id = 54204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totale Tempelzerstörung", description = "Grong ist unsere größte Errungenschaft und er ist bereit für seinen ersten Einsatz!\n\nDie Horde sammelt ihre Truppen bei einem Tempel im Norden.\n\nMagister Umbrics Portal wird Euch schnell dort hinbringen. Dann kann Grong an die Arbeit gehen!", sourceObjective = "Befehlt Grong, die Horde beim Tempel des Propheten zu besiegen.", completion = "Ich weiß nicht, was ich von der Sache halten soll, {name}. \n\nDer Großmacher hat zwar funktioniert, aber Grong wird nie mehr derselbe sein.\n\nIch schätze, er hat es so gewollt... und wenn wir diesen Krieg gewinnen wollen, gab es keine andere Möglichkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54205] = { id = 54205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein hübsches Nickerchen", description = "Ich bin mir nicht sicher, wie lange diese Ketten noch halten. \n\nGrong wird ein kleines Nickerchen machen müssen, bis er einsatzbereit ist.\n\nVerwendet diesen Pfeil. Er ist mit einer Doppeldosis eines Mittels versetzt, das stark genug ist, ein Terrorhorn ins Land der Träume zu schicken, also sollte es funktionieren. \n\nGrong würde sicher wollen, dass Ihr das übernehmt.", sourceObjective = "Schießt mit dem Betäubungspfeil auf Grong.", progress = "Los, trefft Grong mit dem Pfeil. Er wird nichts spüren, das versichere ich Euch.", completion = "Grong wird als wahrer Held der Allianz in die Geschichte eingehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54206] = { id = 54206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schläfer", sourceObjective = "Meldet Euch bei Halford Wyrmbann im Hafen von Boralus.", completion = "Seid Ihr da ganz sicher? Unsere Geheimwaffe ist ein Gorilla?\n\nNun, ich werde wohl darauf vertrauen müssen, dass die Gnome wissen, was sie tun.\n\nVielen Dank für Euren Bericht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54207] = { id = 54207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückeroberung des Außenpostens", description = "Wir komm' mit dem Rest der Allianz schon klar. Ich hab 'nen Bericht erhalt'n, dass Hexfürst Raals Streitkräfte weiter vorne Probleme ham.\n\nEr behauptet, dass Nazmir unter 'nem noch dickeren Nebel liegt. Die Allianz hat wohl irgendwelche Tricks auf Lager, um uns aufzuhalt'n.\n\nGeht nach Nazmir un' seht, wie Ihr Hexfürst Raal helf'n könnt. Wir müss'n zur Flotte gelang'n un' die Allianz vernicht'n!", sourceObjective = "Trefft Euch mit Hexfürst Raal in Nazmir.", completion = "Ich wünschte, ich hätt' bess're Nachricht'n für Euch un' Prinzessin Talanji.", sourceObjectiveStatus = "unverified-source-field" }
quests[54208] = { id = 54208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das reinste Minenfeld", description = "Die Allianz hält unseren Vormarsch mit diesem merkwürdigen Nebel und den ganzen platzierten Fallen enorm auf.\n\nWir werden zu viele Verluste erleiden, wenn wir unsere Truppen einfach durch dieses fallenverseuchte Gebiet marschieren lassen.\n\nIch habe gehört, dass Ihr ein Profi im Herumschleichen seid. Setzt Euer Talent ein und entschärft die Fallen in diesem Gebiet.\n\nIch werde mich darum kümmern, dass wir die Teile der Goblins von der Allianz zurückholen, während Ihr diese Fallen neutralisiert.", sourceObjective = "Entschärft 10 Fallen im Gefallenen Außenposten.", completion = "Gut, unsere Armee ist jetzt abmarschbereit. Rokhan und ich haben genug Teile gefunden, damit die Goblins ihre Maschine wieder zusammenbauen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[54211] = { id = 54211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kein Goblin bleibt zurück", description = "He! Wir müssen den Rest des Goblintrupps einsammeln, wenn wir den A.F.M.O.D. reparieren wollen!\n\nAlso, unser Mech ist im Eimer. Das war verdammt hart. Der Rest des Goblintrupps versteckt sich da draußen und wartet auf die Meldung, dass die Lage wieder sicher ist.\n\nNehmt dieses Ortungsgerät mit. Es schlägt aus, wenn Ihr in der Nähe eines Truppmitglieds seid. Und wenn Ihr dann ganz nah dran seid, solltet Ihr sie sehen können.\n\nDie Truppmitglieder in der Nähe wissen dann, dass sie ihr Versteck verlassen und hierher zurückkommen können.\n\nWenn wir die richtigen Goblins und Teile zusammenhaben, vernichten wir die Allianz im Handumdrehen!", sourceObjective = "Rettet den Goblintrupp.", completion = "Es fühlt sich verdammt gut an, die Truppe wieder beisammen zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54212] = { id = 54212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den A.F.M.O.D. wieder zusammenbauen", description = "Also, wir werden die Allianz durch diesen irren Nebel angreifen. Wir müssen die Ruinen von Zo'bal zurückerobern.\n\nUnd wenn wir den A.F.M.O.D. reparieren, wird das auch das reinste Kinderspiel. Was der A.F.M.O.D. ist? Unser abgefahrener fliegender Mechaoberdampfhammer natürlich! \n\nDie Allianz hat ihn bei ihrem ersten Angriff ramponiert und ein paar Teile davon erbeutet. Holt uns die Teile zurück, dann haben wir das Ding in null Komma nichts repariert!", sourceObjective = "Beschafft 10 A.F.M.O.D.-Teile von gilnearischen Wegelagerern und Schildwachen der Nachtelfen.", progress = "Habt Ihr die Teile? Was genau wohin muss, kriegen wir schon raus, wenn wir alles beisammenhaben.", completion = "Super! Damit können wir das Ding ganz fix reparieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[54213] = { id = 54213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es lebt!", description = "Der A.F.M.O.D. ist repariert und läuft einwandfrei! Ähm, er hat momentan bloß keine Energie.\n\nPrinzessin Talanji kann uns da bestimmt weiterhelfen. Fragt sie, ob sie dem Mech Starthilfe geben kann!\n\nSobald wir hier bereit sind, mähen wir die Allianz nieder, erobern die Ruinen von Zul'jan zurück und rücken weiter vor, um die Flotte zu vernichten!", sourceObjective = "Sprecht mit Talanji, um den A.F.M.O.D. aufzuladen.", completion = "Hahaha! Es wird Zeit, dass wir denen zeigen, wo der Hammer hängt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54224] = { id = 54224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Ruinen von Zul'jan", description = "Generalin Rakera is' mit der Armee vorgerückt. Raal und seine Streitmacht sitz'n so lange fest, bis wir dies'n Nebel hier loswerd'n.\n\nIhr müsst den A.F.M.O.D. steuern und unsrer Armee helf'n, die Ruinen von Zul'jan zurückzuerobern. Nur so könn' wir weiterkomm' un' die Allianz un' diesen Nebel aufhalt'n.\n\nRokhan un' ich werden Euch begleit'n. Die Allianz muss seh'n, dass wir schnell un' entscheidend sieg'n. \n\nUnsre Feinde soll'n vor uns knie'n un' um Gnade winseln, bevor sie sterb'n. So vergelt'n wir die Schändung unsrer Erde.", sourceObjective = "Bemannt den A.F.M.O.D. und erobert die Ruinen von Zul'jan zurück.", completion = "Das letzte Mal, als ich in Zul'jan war, hatt'n wir 'ne zusammengeschusterte Armee mit den Trupp'n unsrer Verbündeten in Nazmir.\n\nJetzt ham wir die geballte Streitmacht meines Reichs und der Horde. Marschieren wir vorwärts!", sourceObjectiveStatus = "unverified-source-field" }
quests[54225] = { id = 54225, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Das Große Siegel", description = "Eure Anhänger haben Euch einen Bericht über die Mission am Großen Siegel geschickt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und ein Missionsbefehlstisch errichtet wurde.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt Euren Missionsbericht zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission zum Großen Siegel?", completion = "Die Mission im Großen Siegel scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54231] = { id = 54231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Das Große Siegel", description = "Die Mission im Großen Siegel war ein Erfolg. Gut gemacht, {name}.\n\nEin Missionsbefehlstisch steht nun dort zur Verfügung.\n\nReist zum Großen Siegel und sorgt dafür, dass die Arbeit unserem Qualitätsstandard entspricht.", sourceObjective = "Untersucht den Missionsbefehlstisch im Großen Siegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[54236] = { id = 54236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[54237] = { id = 54237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Togoth Grobfaust" }
quests[54239] = { id = 54239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Die Ruinen von Zul'jan", description = "Eure Anhänger haben Euch einen Bericht über die Mission in den Ruinen von Zul'jan geschickt.\n\nDarin wird erklärt, dass die Mission ein Erfolg war und die Macht der Loa zugenommen hat, wodurch Segen ab sofort länger bestehen bleiben.\n\nBringt den Bericht zu Nathanos Pestrufer an Bord der Klagelied.", sourceObjective = "Bringt Euren Missionsbericht zu Nathanos Pestrufer.", progress = "Gibt es Neuigkeiten über die Mission zu den Ruinen von Zul'jan?", completion = "Die Mission in den Ruinen von Zul'jan scheint ein Erfolg gewesen zu sein. Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54240] = { id = 54240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Die Ruinen von Zul'jan", description = "Die Mission in den Ruinen von Zul'jan war ein Erfolg. Gut gemacht, {name}.\n\nDie Segen der Loa sind nun mächtiger und werden Euch bei jedem Eurer Aufenthalte in Zandalar gewährt.\n\nReist in die Ruinen von Zul'jan und ehrt einen Altar Eurer Wahl.", sourceObjective = "Wählt den Segen eines Loas an einem der Altäre in den Ruinen von Zul'jan.", sourceObjectiveStatus = "unverified-source-field" }
quests[54243] = { id = 54243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auslöschung à la Goblin" }
quests[54244] = { id = 54244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Ecke gedrängt", description = "Generalin Rakera hat schon damit begonn', unsre Truppen für das nächste Ziel zu mobilisier'n: Zalamar.\n\nWenn wir die Allianz dort vernichtet ham, könn' wir weiter zur Küste vorstoß'n un' die Quelle von diesem Nebel beseitig'n.\n\nDann kann sich die Allianz nich' mehr versteck'n. Wir werd'n ihre Flotte einkreisen un' diesen Krieg ein für alle Mal beend'n.\n\nDie werd'n sich noch wünsch'n, sie hätt'n Nazmir nie betret'n.\n\nKommt! Reit'n wir zusamm' nach Zalamar, um unsren Krieg zu gewinn'!", sourceObjective = "Reitet mit Prinzessin Talanji und Rokhan nach Zalamar.", completion = "Wir ham die Armee der Allianz in die Ecke gedrängt. Jetz' müss'n wir ihr bloß noch den Rest geb'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54245] = { id = 54245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritauseinandersetzung" }
quests[54246] = { id = 54246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azeritauseinandersetzung" }
quests[54249] = { id = 54249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zandalarigerechtigkeit", description = "Wir müss'n die verbleib'nden Truppen der Allianz in Zalamar auslösch'n. Dann werd'n wir die Quelle von dem Nebel find'n... un' damit auch ihre Flotte.\n\nRokhan wird die Gegend auskundschaft'n, um diesen Telaamon zu find'n. Er scheint der General zu sein, der die Truppen dort kommandiert.\n\nIhr müsst da raus geh'n un' alle Allianztruppen in Zalamar vernicht'n, damit wir sie ein für alle Mal auslösch'n könn'.\n\nFindet Rokhan in Zalamar, sobald sie geschwächt sin'.", sourceObjective = "Besiegt 15 Allianztruppen in Zalamar.", completion = "Wir ham's hier mit der Allianz zu zun. Ich hätt' erwartet, dass sie mehr Soldat'n schick'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54251] = { id = 54251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Botschafter" }
quests[54253] = { id = 54253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bomben los" }
