quests[54257] = { id = 54257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitänin Grünsegel" }
quests[54258] = { id = 54258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Das Vulperaversteck", description = "Eure Anhänger haben uns einen Bericht von der Mission im Vulperaversteck geschickt.\n\nEr besagt, dass die Mission ein Erfolg war und dass uns nun ein Wagen zur Verfügung steht.\n\nÜberbringt Nathanos Pestrufer an Bord der Klagelied den Bericht.", sourceObjective = "Bringt Euren Missionsbericht zu Nathanos Pestrufer.", progress = "Habt Ihr schon Neuigkeiten bezüglich der Mission im Vulperaversteck?", completion = "Es scheint, als war die Mission im Vulperaversteck ein Erfolg. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54260] = { id = 54260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Das Vulperaversteck", description = "Die Mission am Vulperaversteck war ein voller Erfolg. Gut gemacht, {name}.\n\nDer Wagenführer ist für Eure Hilfe äußerst dankbar und bereit, den Gefallen zu erwidern.\n\nReist zum Vulperaversteck und sprecht mit dem Wagenführer, um zu sehen, was er für Euch tun kann.", sourceObjective = "Sprecht mit dem Wagenführer am Vulperaversteck.", completion = "Ihr könnt Gift darauf nehmen, dass ich froh bin, den Treulosen entkommen zu sein! Ich danke Euch von ganzem Herzen!\n\nFalls Ihr jemals in einem Wagen mitfahren wollt, sagt mir einfach Bescheid.\n\nAch was, steigt einfach jetzt ein!", sourceObjectiveStatus = "unverified-source-field" }
quests[54262] = { id = 54262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Brennadam", description = "Eure Anhänger haben Euch einen Bericht über die Mission in Brennadam geschickt.\n\nDarin steht, dass es ihnen gelungen ist, Zugriff auf einen fahrbaren Ernter zu bekommen.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Brennadam?", completion = "Die Mission, unseren Außenposten bei Brennadam zu verbessern, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr höchstpersönlich den Ausbau beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54263] = { id = 54263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Brennadam", description = "Die Mission in Brennadam war ein voller Erfolg. Gut gemacht, {name}.\n\nJetzt haben wir Zugriff auf einen, wie man hört, überaus schnellen Ernter, den Ihr steuern könnt. Klingt seltsam in meinen Ohren, aber was weiß ich schon?\n\nReist nach Brennadam und erfahrt mehr über diesen Ausbau.", sourceObjective = "Sprecht mit Henning Haraldsen in Brennadam.", completion = "Also, klar, er sieht nicht nach viel aus, aber Mannomann, wenn der erstmal in Schwung kommt, gibt's kein Halten!\n\nWollt Ihr ihn mal ausprobieren?", sourceObjectiveStatus = "unverified-source-field" }
quests[54265] = { id = 54265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befehle von Azshara", description = "Das sind Befehle auf diesem Medaillon. Den Naga wurde befohlen, über unsere Küsten herzufallen und nach mächtigen Artefakten zu suchen.\n\n<Kojo schaut Euch nachdenklich an.>\n\nIch hörte Geschichten über einen Priester, der mit einem schrecklichen Dolch gegen die Brennende Legion gekämpft haben soll. Es heißt, dass die Klinge... Xal'atath... von den Geheimnissen der Tiefe flüstert. Das könnte unsere beste Gelegenheit sein, um herauszufinden, wonach die Naga suchen.\n\nIch hörte, die Naga haben einen Altar auf einer Insel im Sturmsangtal. Wenn Ihr Xal'atath dort hinbringt, wird der Dolch vielleicht wertvolle Informationen preisgeben.", sourceObjective = "Nehmt Xal'atath und findet den behelfsmäßigen Altar.", completion = "<Ihr verspürt ein bekanntes Gefühl, als Xal'atath mit Eurem Geist in Kontakt tritt.\n\nEine faszinierende Mischung aus Schrecken und... Entzücken.>", sourceObjectiveStatus = "unverified-source-field" }
quests[54266] = { id = 54266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mörsermeister Zappfritz" }
quests[54267] = { id = 54267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[54268] = { id = 54268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Impulsivantrieb" }
quests[54269] = { id = 54269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemand soll entkommen", description = "Die Allianz bringt mit den Maulwurfmaschinen der Dunkeleis'nzwerge Trupp'n nach Zalamar rein un' wieder raus.\n\nWir müss'n die Maschinen zerstör'n. Wir werd'n Zalamar als unsren vorgeschob'nen Stützpunkt nehm'n, um die Hauptflotte der Allianz anzugreif'n.\n\nMacht die Maschinen unbrauchbar un' sucht dann Rokhan in Zalamar. Er spürt grad das Versteck des Allianzgenerals auf.", sourceObjective = "Vernichtet 4 Maulwurfmaschinen.", completion = "Jetz' sin' die Maulwurfmaschinen kaputt. Wir könn' hier unsre Basis aufschlag'n un' geg'n die Allianzflotte kämpf'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54270] = { id = 54270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiegelscherben", description = "Wir ham Nachricht erhalt'n, dass Telaamon, der lichtgeschmiedete Anführer von diesem Angriff, Spiegelbilder von sich erzeug'n kann un' uns so bezwing'n will.\n\nZwei Zandalari, Hexendoktor Kejabu un' Jo'chunga ham angebot'n, beim Kampf gegen die Spiegelbilder zu helf'n. \n\nIhr müsst sicherstell'n, dass sie überleb'n.\n\nWenn wir diese merkwürdigen Spiegelbilder zerstör'n, wird das Telaamon sicher schwäch'n. Ihr un' Rokhan habt dann leichtes Spiel mit ihm.", sourceObjective = "Besiegt Telaamons Spiegelbilder in Zalamar.", completion = "Es is' schön, Jo'chunga un' Kejabu wiederzuseh'n. Wir brauch'n jede Hilfe, die wir geg'n dies'n Telaamon krieg'n könn'.", sourceObjectiveStatus = "unverified-source-field" }
quests[54271] = { id = 54271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaamons Eliminierung", description = "Telaamon, der Lichtbringer, der dies'n Angriff anführt, is' in Hir'eeks Höhle. Er denkt wohl, er kann's ganz allein mit uns aufnehm'.\n\nWenn er tot is', werd'n die Angriffstrupp'n ins Chaos gestürzt un' wir könn' in aller Ruhe am Ufer lang auf die Allianz losmarschier'n.\n\nUn' hoffentlich find'n wir raus, wo der Nebel herkommt, un' könn' ihn loswerd'n.\n\nWir drei werd'n Telaamon ausm Hinterhalt angreif'n, wenn der Kampf losgeht. Der kommt hier nich' lebend raus.", sourceObjective = "Besiegt Telaamon.", completion = "Telaamon is' besiegt. Wir sollt'n besser los.", sourceObjectiveStatus = "unverified-source-field" }
quests[54272] = { id = 54272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfbots" }
quests[54273] = { id = 54273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampfbots" }
quests[54275] = { id = 54275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Nebel teilen", description = "Es wird Zeit, die Hauptflotte der Allianz zu stell'n. Die is' am Brück'nkopf in der Nähe.\n\nIch spür' schon den dunklen Voodoo vom Nebel dort. Prinzessin Talanji hat befohl'n, das Mojo so schnell wie möglich zu zerstör'n.\n\nIch kann uns echt schnell aus dieser Höhle rausbring'n. Dann reit'n wir mit der Prinzessin un' Rakera un' beend'n das hier endgültig.", sourceObjective = "Reitet mit Prinzessin Talanji und vernichtet die Allianzflotte.", completion = "Das gefällt mir nich', {name}. Wir müss'n uns das näher anseh'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54276] = { id = 54276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger in Gnomeregan", description = "Unsere Ingenieure berichten in letzter Zeit ungewöhnliche Verbrauchsspitzen bei der Stromversorgung in Gnomeregan. Ihr müsst so schnell wie möglich herausfinden, was da los ist.\n\nWir haben uns mit einem der obersten Ingenieure in Verbindung gesetzt, der dafür verantwortlich ist, die Roboter in Gnomeregan unter Kontrolle zu halten, und er hat angeboten, uns zu helfen, hineinzukommen und nach dem Rechten zu sehen.", sourceObjective = "Sucht Mikrozoox außerhalb von Gnomeregan in Dun Morogh.", completion = "Das ist doch nicht möglich! Was geht da drin nur vor?! Ich habe keine Zeit, Eure Fragen zu beantworten oder Euch banale Aufgaben zu geben. Es gibt hier wichtige Dinge zu tun!\n\nOh, Ihr wollt nach Gnomeregan hinein und herausfinden, was dort los ist? Warum sagt Ihr das nicht gleich?", sourceObjectiveStatus = "unverified-source-field" }
quests[54280] = { id = 54280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fliegt ihnen entgegen", description = "Dafür wird der Allianzabschaum zahl'n! Unsre Armee marschiert so schnell wie möglich, um unsre Stadt zu verteidig'n.\n\nReitet mit Raal zurück zum Eingang unsrer Stadt. Wir müss'n die Allianz aufhalt'n!", sourceObjective = "Reitet mit Hexfürst Raal zurück nach Zuldazar.", completion = "Wir könn' nich' weiter, die Allianz is' in meiner Stadt eingefall'n!", sourceObjectiveStatus = "unverified-source-field" }
quests[54281] = { id = 54281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ballistenbombardierung" }
quests[54282] = { id = 54282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht von Dazar'alor", description = "Zandalar wird bereits angegriff'n! Mein Volk flieht un' die Allianz verpestet meine Straßen.\n\nRakeras Späher sag'n, dass Jaina Prachtmeer den Angriff leitet.\n\nSie un' ihresgleichen werden für diesen unverschämt'n Angriff auf mein Volk büß'n. \n\nRuft Eure Verbündet'n zusamm' un' schlagt die Allianz zurück. Wir müss'n mein' Vater schützen un' die Allianz vernicht'n!", sourceObjective = "Besiegt Jaina Prachtmeer in der Schlacht von Dazar'alor.", completion = "Diesen Angriff eine Katastrophe zu nennen, wäre eine Untertreibung. Wir haben unsere Hauptwaffe in diesem Krieg verloren.\n\nIhr habt uns allerdings ein paar Siege beschert. Mekkadrill ist tot und Jaina Prachtmeer schwer verwundet.\n\nRuht Euch aus. Lady Sylvanas wurde darüber informiert, was passiert ist, und plant jetzt gerade einen Gegenangriff.", sourceObjectiveStatus = "unverified-source-field" }
quests[54284] = { id = 54284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Die Schiffbruchhöhe", description = "Eure Anhänger haben Euch einen Bericht über die Mission zur Schiffbruchhöhe geschickt.\n\nDarin steht, dass es ihnen gelungen ist, Zugriff auf eine sehr große Kanone zu bekommen.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission zur Schiffbruchhöhe?", completion = "Die Mission, unseren Außenposten bei der Schiffbruchhöhe zu verbessern, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr höchstpersönlich den Ausbau beaufsichtigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54287] = { id = 54287, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagaangriff!" }
quests[54288] = { id = 54288, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Schiffbruchhöhe", description = "Die Mission an der Schiffbruchhöhe war ein voller Erfolg. Gut gemacht, {name}.\n\nWir haben jetzt eine sehr große Kanone, die eine schnelle Reise zum Tiragardesund verspricht. Ich bin nur froh, dass ich nicht so zu reisen gedenke.\n\nReist nach Schiffbruchhöhe und erfahrt mehr über diesen Ausbau.", sourceObjective = "Sprecht mit TNTina an der Schiffbruchhöhe.", completion = "Ist sie nicht eine wahre Schönheit? Ich weiß, es ist ungewöhnlich, aber das Baby hier kann Euch in null Komma nichts zum Tiragardesund bringen. \n\nWollt Ihr einen Schuss ins Blaue?", sourceObjectiveStatus = "unverified-source-field" }
quests[54295] = { id = 54295, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artilleriemeister Siegesfroh" }
quests[54298] = { id = 54298, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freier Fall" }
quests[54300] = { id = 54300, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glaubensbruch", description = "Die Gläubigen zähl'n zu den angesehensten Leuten in der Gesellschaft der Zandalari. Sie dienen allen andren als Vorbild. Aber dies is' kein Beispiel, dem andre folg'n soll'n.\n\nWir müss'n auf angemessene Weise antwort'n.\n\nPrinzessin Talanji will, dass wir alle verschon'n, die zu Vernunft komm'n. Denkt dran, wenn Ihr welche trefft, die sich ergeb'n.\n\nDem Rest könnt Ihr 'nen schnellen Gnadenstoß verpass'n.", sourceObjective = "Bezwingt 12 verärgerte Priester, Druiden oder Prälaten auf der Terrasse der Auserwählten.", completion = "Die Gläubigen unter uns müss'n allen andren 'n Vorbild sein. Aber wenn sie 'n falsches Vorbild liefern, müss'n wir das korrigier'n.", sourceObjectiveStatus = "unverified-source-field" }
quests[54301] = { id = 54301, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talanjis Gnade", description = "Ich kenn meine Priester, {name}. So 'n Aufstand entsteht nich' aus dem Nichts.\n\nIch hab vieles wiedergutzumach'n, aber noch bin ich nich' Herrscherin. Ich hatte noch keine Zeit, mich angemessen um die Gläubigen von Zandalar zu kümmern. Aber das heißt nich', dass sie verdient hab'n zu leid'n.\n\nBegebt Euch zur Terrasse der Auserwählten und findet alle, die nich' kämpf'n woll'n. Bringt sie in Sicherheit. Ich werd sie nich' für die Taten der andren verantwortlich mach'n.", sourceObjective = "Evakuiert 10 Unbeteiligte von der Terrasse der Auserwählten.", completion = "Das is' 'ne Sorge weniger. Ich dank Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54302] = { id = 54302, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fall von Zuldazar", description = "Es wird Zeit, {name}. Wir haben das Abyssische Szepter und die Bestätigung, dass die Bomben, die in der zandalarischen Flotte platziert wurden, immer noch aktiv sind.\n\nLeider würden wir trotz allem, was uns zur Verfügung steht, einen Frontalangriff gegen das Zandalariimperium verlieren.\n\nUnd aus diesem Grund haben wir einen Plan, die Streitkräfte der Horde und der Zandalari vom Hafen wegzulocken.\n\nMathias Shaw hält ein Treffen in der Nähe ab und bittet um Eure Anwesenheit.", sourceObjective = "Sprecht mit Mathias Shaw im Garten innerhalb von Burg Prachtmeer.", progress = "Ich nehme an, dass Ihr und die Lordadmiralin die Horde zum Teufel geschickt habt?", completion = "Jetzt kennt Ihr den Ernst der Lage. Wir müssen beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54303] = { id = 54303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Marsch nach Nazmir", description = "Ich grüße Euch, {name}. Ich bin Klingenmeister Telaamon und ich habe mich freiwillig gemeldet, diese Mission gegen die Horde anzuführen.\n\nUnsere Streitkräfte sammeln sich vor der Küste von Nazmir. Geht jetzt und trefft mich dort.\n\nWenn alles nach Plan läuft, dann locken wir die Horde von Zandalar weg und beenden diesen Krieg.", sourceObjective = "Trefft Euch mit Jaina Prachtmeer und der Armee der Allianz in Nazmir.", completion = "Alle sind hier. Lasst uns beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54306] = { id = 54306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missionsbericht: Aroms Wehr", description = "Eure Anhänger haben Euch einen Bericht über die Mission nach Aroms Wehr geschickt.\n\nDarin steht, dass es ihnen gelungen ist, sich den Segen des Glutordens zu sichern.\n\nBringt den Bericht zu Hochkommandant Wyrmbann an Bord der Erlösenden Winde.", sourceObjective = "Bringt den Bericht zu Halford Wyrmbann.", progress = "Gibt es Neuigkeiten über die Mission nach Aroms Wehr?", completion = "Die Mission, unseren Außenposten bei Aroms Wehr zu verbessern, war wohl von Erfolg gekrönt. Gut gemacht, {name}.\n\nIch werde Euch entsenden, damit Ihr höchstpersönlich die Beaufsichtigung übernehmt.", sourceObjectiveStatus = "unverified-source-field" }
quests[54307] = { id = 54307, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Außenpostenausbau: Aroms Wehr", description = "Die Mission in Aroms Wehr war ein voller Erfolg. Gut gemacht, {name}.\n\nJetzt werden wir einen Segen des Glutordens erhalten.\n\nReist nach Aroms Wehr und erkundigt Euch über diesen Segen.", sourceObjective = "Sprecht mit Klerikerin Loriette in Aroms Wehr.", completion = "Ja, selbstverständlich, Ihr habt so viel für uns getan, da ist unser Segen das Mindeste, was wir Euch gewähren können.", sourceObjectiveStatus = "unverified-source-field" }
quests[54308] = { id = 54308, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tiefschürfende Angelegenheiten" }
quests[54310] = { id = 54310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser Dorf soll schöner werden", description = "Shaw und ich werden Telaamons Armee unterstützen, bis das Ablenkungsmanöver vorbereitet ist.\n\nAls Erstes müssen wir die Bluttrolle aus ihrem Dorf in der Nähe, Zalamar, vertreiben, um unsere Armee vorwärts zu verlegen.\n\nDa kommt Ihr ins Spiel. Ihr müsst die Bluttrolle angreifen, um ihre Truppen zu schwächen, dann trifft unsere Armee ein.\n\nTelaamon wird vor Ort sein, um Euch zu helfen. Trefft Euch mit ihm, sobald Ihr ihre Streitkräfte geschwächt habt. \n\nIch werde mit Shaw hier sein, um sicherzugehen, dass unsere Truppen nicht entdeckt werden.", sourceObjective = "Besiegt 12 Bluttrolle in Zalamar.", completion = "Wie viele habt Ihr getötet? Hmpf... scheint, als ob wir gleichauf sind. Gute Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[54312] = { id = 54312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nebel des Krieges", description = "Kümmert Euch nicht darum. Ich werde dieses Insekt erledigen. Ihr habt größere Aufgaben vor Euch.\n\nIn diesem Moment bewegt sich unsere Armee durch Zalamar, aber die Horde wird die wahre Größe unserer Streitmacht ohne Schwierigkeiten herausfinden.\n\nSprecht mit Bruder Pike und lasst ihn das Ritual mit dem Abyssischen Szepter ausführen, um Nazmir in dichten Nebel zu hüllen.\n\nEr behauptet, dass diese Illusion auch eine komplette Flotte vor dem Strand erscheinen lassen wird. Hoffen wir, dass es funktioniert.\n\nIch werde zu Euch stoßen, sobald ich mit diesem Schmutzfleck auf dem Boden Azeroths fertig bin.", sourceObjective = "Lasst Bruder Pike das Abyssische Szepter benutzen.", completion = "Wir haben unseren Nebel, jetzt müssen wir uns beeilen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54328] = { id = 54328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kürassier Josiph" }
quests[54329] = { id = 54329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Kriegsressourcen", progress = "Unsere Streitkräfte sammeln sich für die bevorstehende Schlacht. Möchtet Ihr unsere Anstrengungen weiter unterstützen?", completion = "Eine großzügige Spende. Ich werde den Kommandanten von Eurem Beitrag unterrichten." }
quests[54330] = { id = 54330, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Platinerz", progress = "Bestimmte Erze sind derzeit schwer aufzutreiben. Wenn Ihr auf Euren Streifzügen Platin findet, würde das unserer Sache sehr weiterhelfen.", completion = "Vielen Dank für Eure Spende. Das werden wir Euch nicht vergessen." }
quests[54331] = { id = 54331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Winterkuss", progress = "Uns gehen die Kräuter aus. Könnt Ihr welche entbehren?", completion = "Das können wir gut gebrauchen. Vielen Dank." }
quests[54332] = { id = 54332, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sternmoos", progress = "Es is' besser, gut vorbereitet zu sein, als an Versorgungsknappheit zu leid'n. Wenn Ihr also 'n bisschen Sternmoos abzugeben habt, werden wir's sicher zu verwend'n wiss'n.", completion = "Sehr großzügig von Euch, {name}." }
quests[54333] = { id = 54333, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sturmsilbererz", progress = "Wir arbeiten Tag und Nacht daran, Waffen und Rüstung für unsere Truppen zu produzieren. Wir brauchen Erz, so viel wie Ihr entbehren könnt.", completion = "Das sollte vorerst reichen." }
quests[54334] = { id = 54334, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Elektroschocker zur Reittiermotivierung", progress = "Unsere Verbündeten brauchen zu lange, um an die Front zu gelangen. Habt Ihr eine Idee, wie wir das ändern können?", completion = "Das sollte für die notwendige Motivation bei unseren Verbündeten sorgen!" }
quests[54335] = { id = 54335, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Instabiler temporaler Zeitverschieber", progress = "Unsere Heiler sind überlastet, daher benötigen wir alternative Methoden, um uns um unsere Verwundeten zu kümmern.", completion = "Mit einer Spende wie dieser rettet Ihr uns wahrlich unsere Haut." }
quests[54336] = { id = 54336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: XA-1000 Wellengleiter", progress = "Der Feind glaubt, dass wir nur über den Landweg angreifen werden, aber wir werden sie auch vom Meer her flankieren.\n\nBesitzt Ihr vielleicht irgendetwas, das uns bei diesem Vorhaben weiterhelfen könnte?", completion = "Ja! Der eignet sich hervorragend!" }
quests[54337] = { id = 54337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Umbralsplitter", progress = "Schlacht'n gewinnt nur, wer Macht hat. Un' Macht ist 'ne Frage der inn'ren Einstellung.\n\nAber Verzauberung'n tun's zur Not auch, zuma' unsre Vorräte zu Neige geh'n.", completion = "Die sin' sehr schwer zu bekomm', wisst Ihr?\n\nWir wiss'n Eure Spende für unsre Sache zu schätz'n." }
quests[54338] = { id = 54338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Thermobeschleunigter Seuchenverbreiter", progress = "Soldaten verlassen sich in der Schlacht aufeinander. Was sagt Ihr, sollen wir ihnen einen kleinen Moralschub auf dem Schlachtfeld verpassen?", completion = "Unsere Feinde werden die Überraschung ihres Lebens erleben!" }
quests[54339] = { id = 54339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank des drohenden Todes", progress = "Ich könnte wirklich ein paar Gefechtstränke gebrauchen. Habt Ihr welche übrig?", completion = "Ja. Die sind genau richtig." }
quests[54340] = { id = 54340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ring - Siegel des Tempos", progress = "Habt Ihr 'n paar Verzaub'rung'n für mich?", completion = "Das hilft mir echt weiter." }
quests[54341] = { id = 54341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ring - Siegel der Meisterschaft", progress = "Habt Ihr in letzter Zeit etwas Interessantes gefunden?", completion = "Besten Dank." }
quests[54342] = { id = 54342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank der Bluteruption", progress = "Nicht jeder wurde zum mutigen Krieger geboren, aber wer sagt, dass man sich nicht ab und zu wie einer benehmen kann?", completion = "Die sind genau richtig." }
quests[54343] = { id = 54343, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank der Erfrischung" }
quests[54344] = { id = 54344, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Blutrote Tinte", progress = "Die Tinte, die ich suche, entfaltet bei Gebrauch eine sehr große Wirkung. Was meint Ihr? Seid Ihr in der Lage, so etwas aufzutreiben?", completion = "Ja. Das sollte genügen." }
quests[54345] = { id = 54345, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Vertrag: Die Eidgebundenen", progress = "Habt Ihr ein paar Verträge für mich?", completion = "Damit stellen wir sicher, dass unsere Rekruten nicht nur durch Worte an uns gebunden sind." }
quests[54346] = { id = 54346, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gold", description = "Unsere Freunde hier akzeptieren alle möglichen Spenden für unsere Kriegsanstrengungen, aber wenn Ihr mich fragt, wurde noch nie ein Krieg ohne angemessene Finanzierung gewonnen. Ja, genau. Ich rede von Geld! Und zwar eine Menge davon.\n\nWenn Ihr es habt, brauchen wir es!", sourceObjective = "Spendet 1000000 Gold an Zahlmeister Grinsebacke im Hafen von Zandalar.", progress = "Ein {class} wie Ihr hat doch sicherlich etwas Bargeld beiseitegeschafft.\n\nWas meint Ihr? Soll ich Euch ein wenig von Eurer Last befreien?", completion = "Gibt doch nichts Wertvolleres als süßes, süßes Gold.", sourceObjectiveStatus = "unverified-source-field" }
quests[54347] = { id = 54347, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ultramarinblaue Tinte", progress = "Unseren Schreibern geht langsam die Tinte aus. Könntet Ihr uns mit diesem Problem helfen?", completion = "Ihr seid sehr großzügig, {name}. Vielen Dank." }
quests[54348] = { id = 54348, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Tiefseesatin", progress = "Wenn unsere Zauberwirker gut eingekleidet sein sollen, müssen wir dafür sorgen, dass wir die entsprechenden Vorräte haben.\n\nFalls Ihr also einmal gar nicht wisst, wohin mit Eurem ganzen Tiefseesatin, könnt Ihr mir den gerne für unsere Vorräte bringen.", completion = "Unsere Verbündeten werden hocherfreut sein. Danke." }
quests[54349] = { id = 54349, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gischtvernebelter Leinenverband", progress = "Verbände wirken Wunder auf dem Schlachtfeld, besonders, da wir kaum Heiler zur Verfügung haben. Habt Ihr welche übrig?", completion = "Verbindlichsten Dank!" }
quests[54350] = { id = 54350, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gischtvernebeltes Leinennetz", progress = "Unsere Feinde setzen unseren Verbündeten mit Sturmangriffen zu. Wir brauchen etwas, um sie zu verlangsamen.\n\nIch habe gehört, dass Schneider feine Netze produzieren. Ihr habt nicht zufällig welche übrig, oder?", completion = "Die werde ich sofort weitergeben." }
quests[54351] = { id = 54351, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Tiefseebandage", progress = "Wir haben angefangen, Verbände zu bunkern für den Fall, dass wir sie brauchen, um unsere Verbündeten aufzupäppeln. Ich habe einen speziellen Artikel zur Liste hinzugefügt.\n\nWenn Ihr davon etwas übrig habt, werde ich dafür sorgen, dass es dahin gelangt, wo es benötigt wird.", completion = "Damit werden wir so manchen Soldaten wieder zusammenflicken." }
quests[54352] = { id = 54352, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Schimmerschuppentauchanzug", progress = "Wisst Ihr, was unsere Feinde wirklich überraschen würde? Das Unerwartete.\n\nUnd ich habe da genau das Richtige.", completion = "Das werden die niemals kommen sehen!" }
quests[54353] = { id = 54353, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Blutbefleckter Knochen", sourceObjective = "Sammelt 20 Waffen - Unbeirrbare Navigation für Uma'wi im Hafen von Zandalar.", progress = "Knochen haben wir zur Zeit im Überfluss, hauptsächlich von gefallenen Verbündeten und Feinden. Wir brauchen aber stärkere Knochen, am besten von der Fauna dieses Lands.\n\nIhr habt nicht zufällig welche auf Euren Reisen gesammelt?", completion = "Perfekt, das können wir gerade gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54354] = { id = 54354, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Schimmerschuppentauchhelm", sourceObjective = "Sammelt 5 Ringe - Siegel des kritischen Trefferwerts für Uma'wi im Hafen von Zandalar.", progress = "Ich war schon fast fertig damit, die Aufträge für die nächste Lieferung abzuschließen, da ist mir aufgefallen, dass ich gar keine Taucherhelme mehr habe!\n\nDenkt Ihr, Ihr könntet mir dabei helfen, die ausstehenden Bestellungen zu bedienen?", completion = "Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[54355] = { id = 54355, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Nebelschuppe", sourceObjective = "Sammelt 100 Ringe - Siegel der Vielseitigkeit für Uma'wi im Hafen von Zandalar.", progress = "Wir haben kaum noch Material zur Lederverarbeitung. Falls Ihr welches übrig habt, würde das unseren Verbündeten immens helfen, sich auf die kommende Schlacht vorzubereiten.", completion = "Das ist eine ansehnliche Spende. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54356] = { id = 54356, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Spiegelnder Goldberyll", progress = "Verstärkungsedelsteine sind enorm wichtig. Wenn wir den Kampf überstehen wollen, müssen wir vorbereitet sein.", completion = "Eure Spende wird sehr geschätzt." }
quests[54357] = { id = 54357, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Meisterlicher Kubilin", progress = "Habt Ihr geschliffene Kubiline, die Ihr gerne spenden würdet?", completion = "Sehr großzügig von Euch." }
quests[54358] = { id = 54358, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Scharlachdiamant" }
quests[54359] = { id = 54359, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sandschleicher", progress = "Uns gehen die Nahrungsvorräte aus. Könnt Ihr welche für die bevorstehende Schlacht entbehren?", completion = "Ich werde diese Rationen an unsere Verbündeten ausgeben. Ich danke Euch." }
quests[54360] = { id = 54360, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Zähe Lende", progress = "Wenn Ihr mir etwas von diesen zähen Lenden bringt, kann ich mich wieder an die Arbeit machen und alles für die bevorstehende Schlacht vorbereiten.", completion = "Ich werde diese Rationen weiterverteilen.\n\nDanke für Eure Spende." }
quests[54361] = { id = 54361, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Wildbeerenbrot", progress = "Ein paar von diesen Desserts wären eine feine Ergänzung zu unseren Vorräten. Bringt mir ein paar davon und ich verteile sie an unsere Truppen.", completion = "Ich wusste, dass ich mich auf Euch verlassen kann." }
quests[54362] = { id = 54362, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Würziges Steak mit Kartoffeln", progress = "Mit einer ordentlichen Mahlzeit im Bauch werden Eure Verbündeten besser kämpfen. Kommt bei mir vorbei, wenn Ihr die Zutaten dafür findet.", completion = "Keine Sorge, {name}. Ich werd dafür sorgen, dass diese Vorräte unsere Verbündeten erreichen." }
quests[54363] = { id = 54363, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Kriegsressourcen", progress = "Wir sind Teil einer großen Anstrengung. Lasst uns in der kommenden Schlacht gemeinsam kämpfen.", completion = "Habt Dank für Euren Beitrag." }
quests[54364] = { id = 54364, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sternmoos", sourceObjective = "Sammelt 30 Stücke gischtvernebeltes Leinen für Faella im Hafen von Boralus.", progress = "So etwas wie zu viel Sternmoos gibt es nicht. Ich bin lieber überversorgt, als irgendwann ohne Material dazustehen.", completion = "Wie aufmerksam von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[54365] = { id = 54365, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Sturmsilbererz", sourceObjective = "Sammelt 30 Schlachtflaggen: Geist der Freiheit für Faella im Hafen von Boralus.", progress = "Unsere Minenarbeiter schuften sich die Hände blutig, um uns das nötige Material zu beschaffen, aber ihre Ausbeute ist leider begrenzt. Ihr habt nicht zufällig etwas Sturmsilber übrig, oder?", completion = "Fantastisch! Damit kommen wir unserem Ziel wieder etwas näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[54366] = { id = 54366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Winterkuss", sourceObjective = "Sammelt 30 Schlachtflaggen: Phalanxverteidigung für Faella im Hafen von Boralus.", progress = "Unsere Winterkussvorräte werden langsam knapp.\n\nIhr seid nicht zufällig ein Kräuterkundiger? Oder vielleicht kennt Ihr ja einen Kräuterkundigen? Oder vielleicht habt Ihr sogar etwas Winterkuss bei Euch?", completion = "Damit sollten wir wieder im Geschäft sein. Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54367] = { id = 54367, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Platinerz", sourceObjective = "Sammelt 10 Schlachtflaggen: Phalanxverteidigung für Faella im Hafen von Boralus.", progress = "Erz ist heutzutage schon nicht leicht zu beschaffen, und bei Platinerz gestaltet sich die Sache sogar noch schwieriger. Falls Ihr also etwas davon entbehren könntet, würde uns das sehr weiterhelfen.", completion = "Jedes kleine Bisschen hilft. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54368] = { id = 54368, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Instabiler temporaler Zeitverschieber", description = "Es ist an der Zeit, dass wir die Konkurrenz auslöschen, meint Ihr nicht? Mit Eurer Hilfe können wir sicherstellen, dass unsere Verbündeten die benötigten Waren und Rüstungsteile bekommen, um sich auf die anstehende Schlacht vorzubereiten.\n\nSorgen wir dafür, dass unsere Verbündeten gut vorbereitet sind.", sourceObjective = "Spendet 2 Teile raues Leder für Charlane im Hafen von Boralus.", progress = "Unsere Heiler sind überlastet, daher benötigen wir alternative Methoden, um uns um unsere Verwundeten zu kümmern.", completion = "Eine ansehnliche Gabe. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[54369] = { id = 54369, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Elektroschocker zur Reittiermotivierung", description = "Ich mache es kurz: Wir brauchen mehr Schimmerschuppen!\n\nTut mir leid, dass ich so mit der Tür ins Haus falle, aber die Zeit ist knapp.\n\nWenn Ihr auf Euren Reisen auf Schimmerschuppen stoßt, wüsste ich sie sicher zu unserem Vorteil einzusetzen. Unsere Verbündeten gut auszurüsten, ist für die bevorstehende Schlacht von entscheidender Bedeutung, meint Ihr nicht?", sourceObjective = "Spendet 2 Schimmerschuppen an Charlane im Hafen von Boralus.", progress = "Die Ausrüstung unserer Verbündeten hat allerhöchste Priorität. Damit haben wir die nötigen Materialien, um dafür zu sorgen, dass auf dem Schlachtfeld niemand hinterherhinkt.", completion = "Mit Eurer Hilfe werden unsere Soldaten bereit sein, sich in die Schlacht zu stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[54370] = { id = 54370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: XA-1000 Wellengleiter", description = "Ihr seht aus wie ein <Kerl, der/Mädel> das;, nie ohne jede Menge Erz im Gepäck unterwegs ist! Wenn dem so ist, käme uns Eure Hilfe sehr gelegen dabei, ein bisschen mehr von dem Zeug für unsere Kriegsanstrengungen zu sammeln.\n\nAlso, hättet Ihr etwas Erz übrig?", sourceObjective = "Sammelt 2 Brocken Moneliterz für Brandal Dunkelbart im Hafen von Boralus.", progress = "Die Schlacht könnte sich auf die See ausbreiten, also müssen wir darauf vorbereitet sein, unsere Feinde auch dort zu bekämpfen.", completion = "Ob zu Land oder zu Wasser, jetzt können unsere Feinde nirgendwohin fliehen. Vielen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[54371] = { id = 54371, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Thermobeschleunigter Seuchenverbreiter", description = "Nicht nur unsere Verbündeten müssen wir in der bevorstehenden Schlacht schützen, sondern auch unsere verlässlichen Reittiere!\n\nKönnt Ihr uns helfen, damit wir sicherstellen können, dass unsere Verbündeten die bestmögliche Rüstung für den bevorstehenden Kampf erhalten?", sourceObjective = "Sammelt 3 raue Lederharnische für Charlane im Hafen von Boralus.", progress = "Unsere Verbündeten benötigen für die bevorstehende Schlacht offensive Alternativen.", completion = "Damit wird der Feind sein blaues Wunder erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54372] = { id = 54372, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Umbralsplitter", sourceObjective = "Spendet 3 Trommeln des Mahlstroms an Charlane im Hafen von Boralus.", progress = "Schlachten werden von den Mächtigen gewonnen. Und wahre Macht entspringt unserem Inneren.\n\nDoch auch Verzauberungen sind hilfreich... und unsere Vorräte werden knapp.", completion = "Die sind sehr schwer zu bekommen, wisst Ihr?\n\nWir wissen Eure Spende für unsere Sache zu schätzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[54373] = { id = 54373, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ring - Siegel des Tempos", sourceObjective = "Sammelt 2 Stücke kantiges Viridium für Larold Kyne im Hafen von Boralus.", progress = "Wir brauchen mehr Verzauberungen für unsere Truppen!", completion = "Das ist genau das Richtige.\n\nDanke für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[54374] = { id = 54374, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank des drohenden Todes", sourceObjective = "Sammelt 2 Stücke vielseitigen Kyanit für Larold Kyne im Hafen von Boralus.", progress = "Unsere Gefechtstränke gehen zur Neige. Wir würden alles, was Ihr erübrigen könnt, sehr zu schätzen wissen.", completion = "Fabelhaft.", sourceObjectiveStatus = "unverified-source-field" }
quests[54375] = { id = 54375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ring - Siegel der Meisterschaft", sourceObjective = "Sammelt 2 Stücke tödlichen Solstein für Larold Kyne im Hafen von Boralus.", progress = "Habt Ihr welche davon in letzter Zeit gesehen?", completion = "Ihr seid wirklich ein Schatz, wisst Ihr?", sourceObjectiveStatus = "unverified-source-field" }
quests[54376] = { id = 54376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank der Erfrischung", sourceObjective = "Sammelt 2 Kriegsrolle des Schlachtrufs für Liao im Hafen von Boralus.", progress = "Mit Vorbereitungen kommt der Erfolg.", completion = "Meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[54377] = { id = 54377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Blutrote Tinte", description = "Die Erleuchtung erhellt uns den Weg zum Sieg. In der Schlacht kämpfen wir als eine Einheit.\n\nTeilt Eure Erkenntnisse und Fähigkeiten mit mir und man wird Euch Eure Großzügigkeit nie vergessen.", sourceObjective = "Sammelt 20 Kriegsrollen der Intelligenz für Liao im Hafen von Boralus.", progress = "Geistige Erleuchtung bietet Gelegenheiten für den Sieg.", completion = "Für diese Gabe gilt Euch mein tiefster Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[54378] = { id = 54378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Trank der Bluteruption", sourceObjective = "Sammelt 2 Kriegsrollen der Seelenstärke für Liao im Hafen von Boralus.", progress = "In schwierigen Situationen bietet sich die Gelegenheit, Stärke und Durchhaltevermögen zu zeigen.", completion = "Mögen die Vorbereitungen uns leiten und die Tapferkeit von innen heraus leuchten.", sourceObjectiveStatus = "unverified-source-field" }
quests[54379] = { id = 54379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Vertrag: 7. Legion", description = "Seid gegrüßt!\n\nJetzt, da unsere Kriegsanstrengungen in vollem Gange sind, bin ich Eure Ansprechpartnerin für Spenden hinsichtlich Kräuterkunde und Alchemie! Es ist mir eine Freude, Euch kennenzulernen!\n\nDann lasst uns mal sehen... Ah, ja. Sirenenpollen. Gestern Abend unterrichtete man mich, dass die Vorräte zur Neige gehen. Es wäre uns allen eine große Hilfe, wenn Ihr uns durch Euren Beitrag unterstützen könntet.", sourceObjective = "Sammelt 3 Sirenenpollen für Klara Strand im Hafen von Boralus.", progress = "Habt Ihr ein paar Verträge für mich?", completion = "Damit stellen wir sicher, dass unsere Rekruten nicht nur durch Worte an uns gebunden sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[54380] = { id = 54380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gold", description = "Wir haben viel Zeit und Ressourcen darauf verwendet, uns auf den bevorstehenden Kampf vorzubereiten. \n\nIm Zuge der letzten Vorbereitungen werden wir zusätzliche Mittel bereitstellen, damit weitere Ausbildung und Nachschublieferungen auch kurzfristig verfügbar sind.\n\nMöchtet auch Ihr etwas spenden?", sourceObjective = "Spendet 1000000 Gold an Zahlmeister Vauldren im Hafen von Boralus.", progress = "Im Zuge der letzten Vorbereitungen werden wir zusätzliche Mittel bereitstellen, damit weitere Ausbildung und Nachschublieferungen auch kurzfristig verfügbar sind.\n\nMöchtet auch Ihr etwas spenden?", completion = "Wie großzügig von Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[54381] = { id = 54381, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Ultramarinblaue Tinte", description = "Seid gegrüßt, <Reisender/Reisende>.\n\nMan hat mich gebeten, dafür zu sorgen, dass unsere Nahrungsmittelvorräte nie zur Neige gehen, aber in letzter Zeit wird der Fisch knapp. Habt Ihr etwas, was Ihr gern spenden würdet?", sourceObjective = "Sammelt 60 Stücke gegrillten Wels für Senedras im Hafen von Boralus.", progress = "Ich soll dafür sorgen, dass unser Inschriftenkundebedarf kontinuierlich gedeckt ist, aber in letzter Zeit ist der Bestand doch etwas knapp geworden.\n\nKönntet Ihr vielleicht etwas Tinte spenden?", completion = "Wunderbar. Ich werde sicherstellen, dass unsere Schreiber für die bevorstehende Schlacht gut versorgt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[54382] = { id = 54382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Tiefseesatin", description = "Fisch... den gibt's heut Abend auf den Tisch! Sagen jedenfalls unsere Versorgungsoffiziere. Und diese Woche dreht sich bei unseren Gerichten alles um eine köstlichen Zutat: Wels.\n\nWenn wir unsere Verbündeten gut ernähren und mit Fisch versorgen wollen, sollten wir schnellstens mehr Vorräte sammeln und mit den Vorbereitungen beginnen.\n\nWenn Ihr beim Schwimmen mal in einem Schwarm Welse geraten solltet, könnt Ihr sie mir gerne für unsere Vorräte bringen.", sourceObjective = "Sammelt 30 Großmeerwelse für Senedras im Hafen von Boralus.", progress = "Wenn unsere Zauberwirker gut eingekleidet sein sollen, müssen wir dafür sorgen, dass wir die entsprechenden Vorräte haben.\n\nFalls Ihr also einmal gar nicht wisst, wohin mit Eurem ganzen Tiefseesatin, könnt Ihr mir den gerne für unsere Vorräte bringen.", completion = "Unsere Verbündeten werden hocherfreut sein. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[54383] = { id = 54383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Schimmerschuppentauchanzug", description = "He da!\n\nLaut Anweisungen von ganz oben brauchen wir mehr Munition! Etwas mit ein bisschen mehr Kick. Etwas, das niemand erwartet!\n\nNach allem, was ich gehört habe, gibt es eine spezielle frostbasierte Munition, die nur die erfahrensten Ingenieure herstellen. Unsere Munitionsoffiziere wären sicher begeistert, wenn Ihr ein paar Stück davon für mich auftreiben könntet!\n\nVielleicht darf ich sogar ein Exemplar behalten, um es zu untersuchen!", sourceObjective = "Sammelt 3 Teile frostversetzte Munition für Norbert Klickritzel im Hafen von Boralus.", progress = "Ich habe gehört, dass es einen speziellen Unterwasseranzug gibt, der von den erfahrensten Lederverarbeitern hergestellt wird.\n\nUnsere Seetruppen wären sicher begeistert, wenn Ihr ein paar davon auftreiben könntet!", completion = "Beeindruckend! Die sind einfach großartig! Die Qualität der Arbeit allein ist... \n\nVerzeiht, ich lasse mich manchmal mitreißen.\n\nPasst auf Euch auf!", sourceObjectiveStatus = "unverified-source-field" }
quests[54384] = { id = 54384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gischtvernebeltes Leinennetz", description = "Auch wenn wir über gesunde Munitionsbestände verfügen, bleibt es meine Pflicht, zusätzliche Ressourcen zu finden, vor allem solche, die schwerer zu beschaffen sind.\n\nHeute suche ich nach einer ganz bestimmten Art von Munition, und zwar Brandmunition. Ich könnte Eure Hilfe wirklich brauchen, um welche aufzuspüren.", sourceObjective = "Sammelt 5 Teile Brandmunition für Norbert Klickritzel im Hafen von Boralus.", progress = "Unsere Feinde setzen unseren Verbündeten mit Sturmangriffen zu. Wir brauchen etwas, um sie zu verlangsamen.\n\nIch habe gehört, dass Schneider feine Netze produzieren. Ihr habt nicht zufällig welche übrig, oder?", completion = "Die werde ich sofort weitergeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54385] = { id = 54385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Gischtvernebelter Leinenverband", progress = "Verbände wirken Wunder auf dem Schlachtfeld, besonders, da wir kaum Heiler zur Verfügung haben. Habt Ihr welche übrig?", completion = "Spektakulär! Das wird uns eine gewaltige Hilfe sein." }
quests[54386] = { id = 54386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Tiefseebandage", description = "Man weiß nie, wann man es auf dem Schlachtfeld so richtig krachen lassen muss, versteht Ihr? Zum Glück können wir für alle Eventualitäten planen!\n\nWir sind im Begriff, einen besonderen Vorrat an Sprengstoff speziell für jene Situationen anzulegen, in denen wir unseren Standpunkt mit etwas mehr... Nachdruck vermitteln müssen. Ich habe die Liste um ein gewisses Element ergänzt.\n\nWenn Ihr etwas davon übrig habt, werde ich sicherstellen, dass es gut genutzt wird.", sourceObjective = "Sammelt 10 B.R.U.T.Z.L. für Norbert Klickritzel im Hafen von Boralus.", sourceObjectiveStatus = "unverified-source-field" }
quests[54387] = { id = 54387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Blutbefleckter Knochen", sourceObjective = "Sammelt 20 Ringe - Siegel der Vielseitigkeit für Finja Fidibus im Hafen von Boralus.", progress = "Ich weiß, es ist ein bisschen kurzfristig, aber ich versuche, noch ein paar Knochen für unsere nächste Lieferung zu finden.", completion = "Gute Arbeit! Diese Knochen riechen zwar etwas faulig, aber sie werden reichen für das, was wir mit ihnen vorhaben.", sourceObjectiveStatus = "unverified-source-field" }
quests[54388] = { id = 54388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Schimmerschuppentauchhelm", sourceObjective = "Sammelt 5 Ringe - Siegel des kritischen Trefferwerts für Finja Fidibus im Hafen von Boralus.", progress = "Ich war schon fast fertig damit, die Aufträge für die nächste Lieferung abzuschließen, da ist mir aufgefallen, dass ich gar keine Taucherhelme mehr habe!\n\nDenkt Ihr, Ihr könntet mir dabei helfen, die ausstehenden Bestellungen zu bedienen?", completion = "Danke, dass Ihr uns über Wasser haltet. Wo wären wir nur ohne großzügige Leute wie Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[54389] = { id = 54389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Nebelschuppe", sourceObjective = "Sammelt 100 Waffe - Unbeirrbare Navigation für Finja Fidibus im Hafen von Boralus.", progress = "Ich konnte bis vor kurzem noch mit den Bestellungen mithalten. Doch jetzt wird es ohne zusätzliche Hilfe knapp.\n\nWärt Ihr dazu bereit, ein paar Materialien zu spenden?", completion = "Ich wusste, dass ich mich auf Euch verlassen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[54390] = { id = 54390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spenden für die Dunkelküste: Meisterlicher Kubilin", description = "Gutes, herzhaftes Fleisch ist genau die Nahrung, die unsere Verbündeten verdienen, bevor sie in die Schlacht ziehen. Außerdem lässt sich damit ein zünftiger Eintopf zubereiten, genau wie ihn unsere Truppen lieben, wenn die Winde gut stehen und die Nächte kälter werden.\n\nWenn Ihr mir ein paar frische gewürzte Lenden besorgt, bringe ich sie gerne zu unseren Versorgungsoffizieren.", sourceObjective = "Sammelt 20 gewürzte Lenden für Senedras im Hafen von Boralus.", progress = "Unsere Juwelenschleifer arbeiten Tag und Nacht, um für die kommende Schlacht genug Edelsteine vorzubereiten.\n\nFalls Ihr ein paar geschliffene Edelsteine entbehren könnt, würdet Ihr sie etwas entlasten.", completion = "Ich werde sie sofort zu unseren Versorgungsoffizieren bringen.", sourceObjectiveStatus = "unverified-source-field" }
